/* Bài tập HSK4 (tự soạn, original): window.EXERCISES[bài] = {fill, order, read, write} */
window.EXERCISES = {"1":{"fill":[{"q":"他最近工作特别忙，几乎每天都要____到晚上十点。","opts":["结婚","加班","吸引","感动"],"a":1,"exp":"“加班”是làm thêm giờ, hợp với “工作忙, 到晚上十点”."},{"q":"听了这个故事，大家都被他们的爱情____了。","opts":["感动","羡慕","普通","重要"],"a":0,"exp":"“被……感动了” là cách nói đúng; 羡慕 không dùng với 被 trong ngữ cảnh này."},{"q":"我和丈夫的____很不一样，他很安静，我很爱说话。","opts":["原因","事情","性格","月亮"],"a":2,"exp":"Nói về người安静/爱说话 là “性格” (tính cách)."},{"q":"他很____，几句话就能让大家笑起来。","opts":["难过","幽默","重要","简单"],"a":1,"exp":"“幽默” (hài hước) làm mọi người cười; 难过 là buồn."},{"q":"我们有____的兴趣，所以聊天时从来不会没话说。","opts":["浪漫","难过","幽默","共同"],"a":3,"exp":"“共同的兴趣” = sở thích chung."},{"q":"他每天都要工作到很晚，____每天都是十点以后才回家。","opts":["互相","需要","其实","几乎"],"a":3,"exp":"“几乎每天” = hầu như ngày nào cũng."}],"order":[{"chunks":["他","不仅","性格好","而且","很幽默。"],"vi":"Anh ấy không chỉ tính cách tốt mà còn rất hài hước."},{"chunks":["虽然他","工作很忙","但是","每天都回家吃饭。"],"vi":"Tuy anh ấy bận việc nhưng ngày nào cũng về nhà ăn cơm."},{"chunks":["他们","已经","结婚","十年了。"],"vi":"Họ đã kết hôn được mười năm rồi."},{"chunks":["我","特别","羡慕","他们的","幸福生活。"],"vi":"Tôi đặc biệt ngưỡng mộ cuộc sống hạnh phúc của họ."}],"read":{"text":"小林和她丈夫刚认识的时候，两个人的性格差别很大。小林爱说话，丈夫却很安静，朋友们都觉得他们不太适合。可是结婚五年后，大家发现他们过得很幸福。小林说，丈夫不会送花，也不懂浪漫，但是每次她加班回家，桌子上总有一碗热汤。这样的小事常常让她很感动。","vi":"Lúc Tiểu Lâm và chồng mới quen nhau, tính cách hai người khác nhau rất nhiều. Tiểu Lâm hay nói, còn chồng lại rất trầm lặng, bạn bè đều thấy họ không hợp. Nhưng sau năm năm kết hôn, mọi người nhận ra họ sống rất hạnh phúc. Tiểu Lâm kể chồng không biết tặng hoa, cũng không hiểu lãng mạn, nhưng mỗi lần cô tăng ca về nhà, trên bàn luôn có một bát canh nóng. Những việc nhỏ như vậy thường khiến cô rất cảm động.","qs":[{"q":"朋友们一开始为什么觉得小林和她丈夫不适合？","opts":["他们的年龄差别很大","他们的性格很不一样","丈夫的工作太忙","小林不喜欢丈夫"],"a":1,"exp":"Đoạn nói tính cách hai người khác nhau (一个爱说话，一个很安静)."},{"q":"丈夫哪件事让小林很感动？","opts":["常常送花给她","每天陪她逛街","她加班回家时，为她留了热汤","说很多好听的话"],"a":2,"exp":"Bài nói chồng không tặng hoa; điều làm cô cảm động là bát canh nóng chờ sẵn khi cô tăng ca."},{"q":"结婚五年后，大家对他们的看法是什么？","opts":["仍然觉得他们不适合","觉得丈夫应该多说话","觉得小林不该加班","觉得他们过得很幸福"],"a":3,"exp":"Bài viết nói “结婚五年后，大家发现他们过得很幸福”, nên đáp án đúng là 觉得他们过得很幸福 (thấy họ sống rất hạnh phúc); các đáp án còn lại không được nhắc tới hoặc trái với nội dung."}]},"write":[{"word":"羡慕","hint":"Nói bạn ngưỡng mộ bạn thân vì cô ấy có một gia đình hạnh phúc.","model":"我很羡慕我的好朋友，因为她有一个幸福的家。","py":"Wǒ hěn xiànmù wǒ de hǎo péngyou, yīnwèi tā yǒu yí ge xìngfú de jiā.","vi":"Tôi rất ngưỡng mộ bạn thân của mình vì cô ấy có một gia đình hạnh phúc."},{"word":"吸引","hint":"Nói sự hài hước của anh ấy đã thu hút bạn.","model":"他的幽默吸引了我。","py":"Tā de yōumò xīyǐn le wǒ.","vi":"Sự hài hước của anh ấy đã thu hút tôi."},{"word":"加班","hint":"Nói tối nay phải làm thêm nên không thể đi ăn cơm cùng bạn.","model":"今天晚上我要加班，不能和你去吃饭了。","py":"Jīntiān wǎnshang wǒ yào jiābān, bù néng hé nǐ qù chīfàn le.","vi":"Tối nay tôi phải làm thêm giờ, không thể đi ăn cơm với bạn được."}]},"2":{"fill":[{"q":"周末一个人在家，没有事做，真____。","opts":["必须","丰富","无聊","及时"],"a":2,"exp":"Ở nhà một mình không có việc làm thì “无聊” (chán)."},{"q":"你有____的时候，可以给我打电话，我会尽力帮你。","opts":["习惯","镜子","周围","困难"],"a":3,"exp":"“有困难的时候” = lúc gặp khó khăn."},{"q":"医生说他____每天按时吃药，不然病会更重。","opts":["离开","必须","成为","互相"],"a":1,"exp":"“必须” = nhất định phải, hợp với lời dặn của bác sĩ."},{"q":"朋友生病住院了，我想去医院____她。","opts":["陪","介绍","讨厌","丰富"],"a":0,"exp":"“陪她” = ở bên cạnh cô ấy."},{"q":"刚到新城市的时候，我还不太____这里的天气。","opts":["帮助","交流","习惯","丰富"],"a":2,"exp":"“习惯这里的天气” = quen với thời tiết ở đây."},{"q":"他们认识很久了，所以非常____对方的想法。","opts":["生气","了解","陪","丰富"],"a":1,"exp":"“了解对方的想法” = hiểu rõ suy nghĩ của đối phương."}],"order":[{"chunks":["每次","我遇到困难","他都","及时帮助我。"],"vi":"Mỗi lần tôi gặp khó khăn, anh ấy đều giúp đỡ kịp thời."},{"chunks":["朋友","可以","丰富","我们的","生活。"],"vi":"Bạn bè có thể làm cuộc sống của chúng ta phong phú hơn."},{"chunks":["如果","你","脾气不好","就很难","交到朋友。"],"vi":"Nếu bạn tính khí không tốt thì rất khó kết bạn."},{"chunks":["尽管","毕业很多年了","我们","还是","经常联系。"],"vi":"Mặc dù đã tốt nghiệp nhiều năm, chúng tôi vẫn thường xuyên liên lạc."}],"read":{"text":"我和小周是大学同学。刚认识时，我不太喜欢他，因为他脾气不好，常常为小事生气。后来我生病住院，朋友们都忙着考试，只有他每天来医院陪我，还把老师讲的内容及时告诉我。那时我才发现，他其实是个很热情的人。现在我们虽然不在同一个城市，但还是经常联系。","vi":"Tôi và Tiểu Chu là bạn học đại học. Lúc mới quen, tôi không thích anh ấy lắm vì tính khí anh ấy không tốt, hay tức giận vì chuyện nhỏ. Sau này tôi bị ốm phải nằm viện, bạn bè đều bận thi, chỉ có anh ấy ngày nào cũng đến bệnh viện ở bên tôi, còn kịp thời kể cho tôi nội dung thầy cô giảng. Lúc đó tôi mới nhận ra anh ấy thật ra là người rất nhiệt tình. Bây giờ tuy chúng tôi không ở cùng một thành phố nhưng vẫn thường xuyên liên lạc.","qs":[{"q":"作者一开始为什么不太喜欢小周？","opts":["他经常迟到","他的脾气不好","他不爱学习","他不是作者的同学"],"a":1,"exp":"Đoạn nói: 因为他脾气不好，常常为小事生气."},{"q":"作者住院时，小周做了什么？","opts":["给他买了很多水果","帮他请了很长的假","替他参加考试","每天去医院陪他，并告诉他课上的内容"],"a":3,"exp":"Đáp án đúng: 每天去医院陪他，并告诉他课上的内容 (mỗi ngày đến bệnh viện ở bên và kể lại nội dung bài giảng). Bài viết nói rõ “每天来医院陪我，还把老师讲的内容及时告诉我”; các đáp án còn lại không được nhắc đến."},{"q":"毕业后他们的关系怎么样？","opts":["不再联系了","住得很近，每天见面","虽然不在一个城市，但还保持联系","小周去了国外"],"a":2,"exp":"Đoạn cuối nói “bây giờ tuy không ở cùng một thành phố nhưng vẫn thường xuyên liên lạc”, khớp với đáp án 虽然不在一个城市，但还保持联系; các đáp án còn lại (không liên lạc, ở gần gặp mỗi ngày, ra nước ngoài) đều không có trong bài."}]},"write":[{"word":"理解","hint":"Nói bạn hiểu tâm trạng hiện giờ của bạn mình nên không giận cậu ấy.","model":"我很理解朋友现在的心情，所以没有生他的气。","py":"Wǒ hěn lǐjiě péngyou xiànzài de xīnqíng, suǒyǐ méiyǒu shēng tā de qì.","vi":"Tôi rất hiểu tâm trạng hiện giờ của bạn, nên không giận cậu ấy."},{"word":"习惯","hint":"Nói bạn vẫn chưa quen ăn cơm một mình.","model":"我还不习惯一个人吃饭。","py":"Wǒ hái bù xíguàn yí ge rén chī fàn.","vi":"Tôi vẫn chưa quen ăn cơm một mình."},{"word":"帮助","hint":"Cảm ơn bạn đã giúp đỡ khi bạn gặp khó khăn.","model":"谢谢你在我有困难的时候帮助我。","py":"Xièxie nǐ zài wǒ yǒu kùnnan de shíhou bāngzhù wǒ.","vi":"Cảm ơn bạn đã giúp tôi lúc tôi gặp khó khăn."}]},"3":{"fill":[{"q":"明天我要去一家大公司参加____，所以今天晚上得早点儿睡。","opts":["顾客","面试","东西","声音"],"a":1,"exp":"Đáp án 面试 (phỏng vấn): “参加面试” là cụm cố định, đi công ty dự phỏng vấn nên phải ngủ sớm. 顾客 (khách hàng), 东西 (đồ vật), 声音 (âm thanh) đặt vào đều vô nghĩa."},{"q":"第一次见面，他穿得很正式，说话也很有礼貌，给我留下了很好的____。","opts":["印象","判断","影响","约会"],"a":0,"exp":"“留下印象” (để lại ấn tượng) là cách kết hợp từ cố định; 印象 = ấn tượng. 判断 (phán đoán), 影响 (ảnh hưởng), 约会 (hẹn hò) đều không đi với 留下 một cách tự nhiên."},{"q":"开会的时间改了，秘书已经打电话____大家了。","opts":["相信","改变","通知","回答"],"a":2,"exp":"Chỗ trống cần từ nghĩa “báo cho mọi người biết”, nên chọn 通知 (thông báo). 相信 (tin), 改变 (thay đổi), 回答 (trả lời) đều không hợp với “gọi điện ... mọi người”."},{"q":"第一次在很多人面前讲话，他有点儿____，手一直在发抖。","opts":["诚实","顺利","准时","紧张"],"a":3,"exp":"Tay run chứng tỏ tâm trạng 紧张 (căng thẳng, hồi hộp); 诚实 (thành thật), 顺利 (thuận lợi), 准时 (đúng giờ) không giải thích được việc tay run."},{"q":"老板很看重他的____，因为他一个人就能解决很多问题。","opts":["声音","能力","顾客","约会"],"a":1,"exp":"Đáp án 能力 (năng lực): một mình giải quyết được nhiều vấn đề nghĩa là có năng lực, “看重能力” hợp lý. 声音 (giọng nói), 顾客 (khách), 约会 (hẹn hò) không hợp nghĩa."},{"q":"他是个____的人，从来不说谎，大家都愿意相信他。","opts":["紧张","顺利","诚实","重要"],"a":2,"exp":"“从来不说谎、大家都愿意相信他” là tả người 诚实 (thật thà, trung thực); 紧张 (căng thẳng), 顺利 (thuận lợi), 重要 (quan trọng) không hợp nghĩa."}],"order":[{"chunks":["我的同事","每天","都","准时","上班。"],"vi":"Đồng nghiệp của tôi ngày nào cũng đi làm đúng giờ."},{"chunks":["面试的时候","请不要","太紧张。"],"vi":"Lúc phỏng vấn, xin đừng quá căng thẳng."},{"chunks":["你","要","相信","自己的","能力。"],"vi":"Bạn phải tin vào năng lực của chính mình."},{"chunks":["第一次见面时","给顾客","留下好印象","非常重要。"],"vi":"Lần đầu gặp mặt, để lại ấn tượng tốt cho khách hàng là rất quan trọng."}],"read":{"text":"小王上周去一家旅游公司应聘。面试那天，他提前二十分钟就到了，还穿了正式的衬衫。虽然有点儿紧张，但是回答问题时，他说得很清楚，也很诚实。经理说：“你的经验不多，不过你很认真，我们愿意给你一个机会。”第二天，公司打电话通知他下周一开始上班。小王高兴极了。","vi":"Tuần trước, Tiểu Vương đến một công ty du lịch ứng tuyển. Hôm phỏng vấn, anh đến sớm hai mươi phút, còn mặc áo sơ mi trang trọng. Tuy hơi căng thẳng nhưng lúc trả lời câu hỏi, anh nói rất rõ ràng và cũng rất thành thật. Giám đốc nói: “Kinh nghiệm của cậu không nhiều, nhưng cậu rất nghiêm túc, chúng tôi sẵn lòng cho cậu một cơ hội.” Hôm sau, công ty gọi điện thông báo anh bắt đầu đi làm từ thứ Hai tuần sau. Tiểu Vương vui vô cùng.","qs":[{"q":"经理为什么愿意给小王一个机会？","opts":["他有很多工作经验","他是经理的朋友","他认真而且诚实","他回答得特别快"],"a":2,"exp":"Giám đốc nói kinh nghiệm không nhiều nhưng rất 认真 (nghiêm túc), và bài nói anh ấy trả lời 诚实 (thành thật), nên chọn “认真而且诚实”. “Nhiều kinh nghiệm” sai vì kinh nghiệm ít; các ý còn lại không có trong bài."},{"q":"关于面试那天的小王，下面哪一项正确？","opts":["他迟到了几分钟","他提前到了","他穿得很随便","他一点儿也不紧张"],"a":1,"exp":"Bài nói anh ấy 提前二十分钟就到了 (đến sớm 20 phút); anh ấy mặc đồ trang trọng và có hơi căng thẳng, nên các đáp án đến muộn, ăn mặc tùy tiện, không căng thẳng đều sai."},{"q":"公司让小王什么时候开始上班？","opts":["面试那天","第二天","这个星期五","下周一"],"a":3,"exp":"Đáp án 下周一: “第二天” chỉ là lúc công ty gọi điện báo, còn thời điểm bắt đầu đi làm là 下周一 (thứ Hai tuần sau). Các đáp án khác nhầm thời gian."}]},"write":[{"word":"约会","hint":"Nói rằng tối mai bạn có một cuộc hẹn quan trọng nên không thể tăng ca.","model":"明天晚上我有一个重要的约会，不能加班。","py":"Míngtiān wǎnshang wǒ yǒu yí ge zhòngyào de yuēhuì, bù néng jiābān.","vi":"Tối mai tôi có một cuộc hẹn quan trọng nên không thể tăng ca."},{"word":"相信","hint":"Nói với bạn mình rằng bạn tin chắc cậu ấy sẽ vượt qua buổi phỏng vấn lần này.","model":"我相信你一定能通过这次面试。","py":"Wǒ xiāngxìn nǐ yídìng néng tōngguò zhè cì miànshì.","vi":"Tôi tin chắc bạn nhất định sẽ vượt qua buổi phỏng vấn lần này."},{"word":"影响","hint":"Nói rằng ngủ quá muộn sẽ ảnh hưởng đến công việc ngày hôm sau.","model":"睡得太晚会影响第二天的工作。","py":"Shuì de tài wǎn huì yǐngxiǎng dì-èr tiān de gōngzuò.","vi":"Ngủ quá muộn sẽ ảnh hưởng đến công việc ngày hôm sau."}]},"4":{"fill":[{"q":"按照公司的____，我们下个月要开一家新商店。","opts":["成绩","方法","计划","消息"],"a":2,"exp":"“按照公司的计划” (theo kế hoạch của công ty) là cách nói cố định; 计划 = kế hoạch. 成绩 (thành tích), 方法 (phương pháp), 消息 (tin tức) không đi với 按照 trong câu này."},{"q":"电脑突然坏了，谁能帮我____这个问题？","opts":["提醒","解决","感谢","离开"],"a":1,"exp":"“解决问题” (giải quyết vấn đề) là cách kết hợp từ quen thuộc. 提醒 (nhắc nhở), 感谢 (cảm ơn), 离开 (rời đi) không đi với 问题."},{"q":"今年年底，公司给每个人发了一千元____。","opts":["办法","时间","责任心","奖金"],"a":3,"exp":"Động từ “发” (phát) đi với tiền, 一千元 chỉ có thể là 奖金 (tiền thưởng); 办法 (cách), 时间 (thời gian), 责任心 (tinh thần trách nhiệm) không thể “phát”."},{"q":"他刚工作两年，还没有什么工作____，你多帮帮他。","opts":["经验","工资","奖金","消息"],"a":0,"exp":"Đáp án 经验 (kinh nghiệm): mới đi làm hai năm nên thiếu “工作经验”. 工资 (lương), 奖金 (tiền thưởng), 消息 (tin tức) không đi với “还没有什么…” ở nghĩa này."},{"q":"刚搬到新城市，他很快就____了这里的生活。","opts":["保证","积累","解决","适应"],"a":3,"exp":"“适应生活” nghĩa là thích nghi với cuộc sống mới; 适应 = thích nghi. 保证 (bảo đảm), 积累 (tích lũy), 解决 (giải quyết) không hợp với “生活” và ngữ cảnh chuyển đến thành phố mới."},{"q":"请放心，我____按时把东西送到你家。","opts":["感谢","保证","适应","成功"],"a":1,"exp":"保证 (đảm bảo) diễn tả lời hứa chắc chắn sẽ làm: “我保证按时送到”. 感谢 (cảm ơn), 适应 (thích nghi), 成功 (thành công) không dùng để hứa với người khác."}],"order":[{"chunks":["小张","按时","完成了","这个月的","工作。"],"vi":"Tiểu Trương đã hoàn thành đúng hạn công việc của tháng này."},{"chunks":["你","不要","只想着","赚钱。"],"vi":"Bạn đừng chỉ nghĩ đến kiếm tiền."},{"chunks":["虽然","工作很忙","但是","他从来不","迟到。"],"vi":"Tuy công việc rất bận nhưng anh ấy chưa bao giờ đến muộn."},{"chunks":["我们","一定要","把问题","解决好。"],"vi":"Chúng ta nhất định phải giải quyết tốt vấn đề."}],"read":{"text":"李明大学毕业后，进了一家小公司。刚开始，他的工资不高，也没有奖金，所以想换工作。经理告诉他：“你现在最重要的是学习，不是赚钱。”李明决定再努力一年。他每天提前到公司，认真做好每件事。一年后，他积累了很多经验，还成功地完成了一个大计划。公司提高了他的工资，还让他负责新的工作。","vi":"Sau khi tốt nghiệp đại học, Lý Minh vào làm ở một công ty nhỏ. Lúc mới bắt đầu, lương của anh không cao, cũng không có tiền thưởng nên muốn đổi việc. Giám đốc nói với anh: “Điều quan trọng nhất của cậu lúc này là học hỏi, không phải kiếm tiền.” Lý Minh quyết định cố gắng thêm một năm. Mỗi ngày anh đến công ty sớm, làm tốt từng việc một cách nghiêm túc. Một năm sau, anh tích lũy được nhiều kinh nghiệm và hoàn thành thành công một kế hoạch lớn. Công ty tăng lương cho anh và còn giao anh phụ trách công việc mới.","qs":[{"q":"李明为什么想换工作？","opts":["公司离家太远","经理不喜欢他","工作太累","工资不高，也没有奖金"],"a":3,"exp":"Bài nêu rõ lương không cao, lại không có tiền thưởng nên anh ấy muốn đổi việc, đáp án đúng là 工资不高，也没有奖金; các lý do khác (xa nhà, sếp ghét, quá mệt) không được nhắc đến."},{"q":"经理认为李明现在应该怎么做？","opts":["马上换工作","多赚一些钱","先好好学习","去别的公司看看"],"a":2,"exp":"Đáp án 先好好学习: giám đốc nói điều quan trọng nhất lúc này là học hỏi chứ không phải kiếm tiền, nên không khuyên đổi việc hay kiếm tiền."},{"q":"一年以后，李明的情况怎么样？","opts":["经验多了，还负责新的工作","换到了别的公司","工资比以前少了","决定不再工作"],"a":0,"exp":"Bài nói sau một năm anh ấy 积累了很多经验 (tích lũy nhiều kinh nghiệm), được tăng lương và phụ trách công việc mới, nên chọn “经验多了，还负责新的工作”; anh không đổi công ty, lương không giảm, cũng không nghỉ việc."}]},"write":[{"word":"责任心","hint":"Nói rằng điều cần nhất khi làm công việc này là tinh thần trách nhiệm.","model":"做这份工作最需要的是责任心。","py":"Zuò zhè fèn gōngzuò zuì xūyào de shì zérènxīn.","vi":"Điều cần nhất khi làm công việc này là tinh thần trách nhiệm."},{"word":"感谢","hint":"Cảm ơn người khác vì hôm qua đã giúp bạn giải quyết vấn đề đó.","model":"感谢你昨天帮我解决了那个问题。","py":"Gǎnxiè nǐ zuótiān bāng wǒ jiějué le nàge wèntí.","vi":"Cảm ơn bạn hôm qua đã giúp tôi giải quyết vấn đề đó."},{"word":"积累","hint":"Nói rằng ngày nào anh ấy cũng đọc sách nên dần dần tích lũy được không ít kiến thức.","model":"他每天都读书，慢慢积累了不少知识。","py":"Tā měitiān dōu dú shū, mànman jīlěi le bù shǎo zhīshi.","vi":"Ngày nào anh ấy cũng đọc sách, dần dần tích lũy được không ít kiến thức."}]},"5":{"fill":[{"q":"这件外套样子不错，可是穿起来太大了，不____我。","opts":["寄","理解","适合","购买"],"a":2,"exp":"适合 (phù hợp): “不适合我” nghĩa là áo quá rộng, không vừa với tôi. 寄 (gửi), 理解 (hiểu), 购买 (mua) đặt vào đây không thông nghĩa."},{"q":"买了很多不需要的东西放在家里不用，真是____钱。","opts":["吸引","浪费","寄","流行"],"a":1,"exp":"“浪费钱” (lãng phí tiền) nghĩa là tiêu tiền vào thứ vô dụng, hợp với ý “mua đồ không cần, để không dùng”; 吸引 (thu hút), 寄 (gửi), 流行 (thịnh hành) không hợp nghĩa."},{"q":"这家网店的衣服____很好，我穿了三年都没有坏。","opts":["价格","样子","原因","质量"],"a":3,"exp":"Đáp án 质量 (chất lượng): mặc ba năm không hỏng cho thấy chất lượng tốt, và 质量 là danh từ làm chủ ngữ được. 价格 (giá), 样子 (kiểu dáng), 原因 (nguyên nhân) không hợp."},{"q":"网上购物很____，在家点一下，东西就会寄到办公室。","opts":["方便","浪费","适合","寄"],"a":0,"exp":"Sau “很” cần tính từ; 方便 (tiện lợi) hợp nghĩa vì ở nhà bấm một cái là hàng gửi tới văn phòng. 浪费 (lãng phí) sai nghĩa, 适合 (phù hợp) không hợp ngữ cảnh, 寄 (gửi) là động từ nên không đứng sau “很”."},{"q":"买鞋的时候，我____考虑的是舒服，其次才是好看。","opts":["尤其","其次","首先","即使"],"a":2,"exp":"Vế sau có 其次 (thứ hai), nên vế trước dùng 首先 (trước hết), tạo thành cấu trúc “首先……其次……”. 尤其 (đặc biệt) và 即使 (cho dù) không tạo cặp này; 其次 đã có ở vế sau."},{"q":"他很喜欢买衣服，____是打折的时候，常常一次买好几件。","opts":["如果","尤其","因为","即使"],"a":1,"exp":"“尤其是” nghĩa là đặc biệt là, nhấn mạnh lúc giảm giá anh ấy mua nhiều nhất; 如果 (nếu), 因为 (bởi vì), 即使 (cho dù) không nối được ý câu này."}],"order":[{"chunks":["这个周末","我","打算","去商场","买一件外套。"],"vi":"Cuối tuần này tôi định đến trung tâm thương mại mua một cái áo khoác."},{"chunks":["这条裤子","质量很好","而且","价格也不贵。"],"vi":"Chiếc quần này chất lượng rất tốt, hơn nữa giá cũng không đắt."},{"chunks":["如果东西不合适","你可以","把它寄回去。"],"vi":"Nếu đồ không vừa, bạn có thể gửi trả lại."},{"chunks":["网上购物","变得","越来越","方便了。"],"vi":"Mua sắm trên mạng ngày càng trở nên tiện lợi."}],"read":{"text":"姐姐以前喜欢去商场买衣服，现在更喜欢在网上购物，因为网上的东西多，价格也便宜。不过上个月，她买了一条裙子，照片上看上去很好看，穿上却太小了。卖家说可以换，但是要她自己花钱寄回去。姐姐觉得很麻烦，最后没有换。她说，以后买东西不能只看照片，还要先问清楚，不能因为便宜就马上买。","vi":"Chị gái tôi trước đây thích đến trung tâm thương mại mua quần áo, bây giờ chị thích mua sắm trên mạng hơn, vì trên mạng đồ nhiều, giá cũng rẻ. Nhưng tháng trước chị mua một chiếc váy, nhìn trong ảnh rất đẹp, mặc vào lại quá chật. Người bán nói có thể đổi, nhưng chị phải tự bỏ tiền gửi trả lại. Chị thấy rất phiền nên cuối cùng không đổi. Chị nói sau này mua đồ không thể chỉ xem ảnh, còn phải hỏi rõ trước, không thể vì rẻ mà mua ngay.","qs":[{"q":"姐姐为什么现在更喜欢网上购物？","opts":["网上的东西多，价格也便宜","网上的衣服都很流行","商场里没有裙子","卖家会免费送东西"],"a":0,"exp":"Đáp án 网上的东西多，价格也便宜: câu đầu bài đọc nói rõ lý do này. Các đáp án còn lại không được bài nhắc tới như lý do thích mua online."},{"q":"姐姐最后为什么没有换那条裙子？","opts":["她觉得裙子很好看","寄回去要自己花钱，她觉得麻烦","卖家不同意换","她忘记了"],"a":1,"exp":"Người bán cho đổi nhưng chị phải tự trả tiền gửi trả lại, chị thấy phiền (麻烦) nên cuối cùng không đổi; các đáp án khác không đúng với bài."},{"q":"这件事以后，姐姐的想法是什么？","opts":["再也不在网上买东西","只买便宜的东西","买之前要问清楚，不能只因为便宜就买","只相信照片"],"a":2,"exp":"Chị nói sau này mua đồ không chỉ nhìn ảnh, phải hỏi rõ trước và không vì rẻ mà mua ngay, khớp với đáp án “买之前要问清楚，不能只因为便宜就买”. Các đáp án kia (không mua online nữa, chỉ mua đồ rẻ, chỉ tin ảnh) đều trái với ý bài."}]},"write":[{"word":"考虑","hint":"Nói rằng trước khi mua điện thoại, bạn sẽ cân nhắc giá cả trước.","model":"买手机以前，我要先考虑一下价格。","py":"Mǎi shǒujī yǐqián, wǒ yào xiān kǎolǜ yíxià jiàgé.","vi":"Trước khi mua điện thoại, tôi phải cân nhắc giá cả trước."},{"word":"流行","hint":"Nói rằng năm nay kiểu áo sơ mi màu xanh này rất thịnh hành.","model":"今年很流行这种蓝色的衬衫。","py":"Jīnnián hěn liúxíng zhè zhǒng lánsè de chènshān.","vi":"Năm nay loại áo sơ mi màu xanh này rất thịnh hành."},{"word":"尤其","hint":"Nói rằng bạn thích mua sắm trên mạng, đặc biệt là mua sách.","model":"我喜欢网上购物，尤其是买书。","py":"Wǒ xǐhuan wǎngshàng gòuwù, yóuqí shì mǎi shū.","vi":"Tôi thích mua sắm trên mạng, đặc biệt là mua sách."}]},"6":{"fill":[{"q":"这家商店的东西很便宜，所以每天都有很多____。","opts":["词典","地图","节日","顾客"],"a":3,"exp":"Người đến cửa hàng mua đồ gọi là 顾客 (khách hàng); 词典 (từ điển), 地图 (bản đồ), 节日 (ngày lễ) không chỉ người, không hợp với “很多” ở đây."},{"q":"买满五百元，就可以____办一张会员卡。","opts":["免费","获得","举行","降低"],"a":0,"exp":"Đáp án 免费 (miễn phí): “免费办” nghĩa là làm thẻ không mất tiền, đứng trước động từ 办 làm trạng ngữ. 获得 (đạt được), 举行 (tổ chức), 降低 (hạ thấp) không hợp."},{"q":"这个周末书店有一个打折____，欢迎大家来。","opts":["顾客","地图","活动","小说"],"a":2,"exp":"“打折活动” (chương trình giảm giá) là cách nói thông dụng; 活动 = hoạt động, chương trình. 顾客 (khách hàng), 地图 (bản đồ), 小说 (tiểu thuyết) không đi sau “打折”."},{"q":"这个行李箱要是坏了，一年内商店负责____。","opts":["降低","修理","感谢","获得"],"a":1,"exp":"Đồ vật hỏng thì cần 修理 (sửa chữa), “负责修理” rất tự nhiên. 降低 (hạ thấp), 感谢 (cảm ơn), 获得 (đạt được) không hợp nghĩa."},{"q":"他参加比赛，____了第一名。","opts":["举行","降低","免费","获得"],"a":3,"exp":"“获得第一名” là cách nói cố định, nghĩa là giành được hạng nhất; 举行 (tổ chức), 降低 (hạ thấp), 免费 (miễn phí) không đi với “第一名”."},{"q":"春天来了，商场把冬天衣服的价格____了很多。","opts":["降低","获得","支持","感谢"],"a":0,"exp":"Đáp án 降低 (hạ thấp): “价格降低了” nghĩa là giá giảm, khớp với việc giảm giá cuối mùa. 获得 (đạt được), 支持 (ủng hộ), 感谢 (cảm ơn) không đi với 价格."}],"order":[{"chunks":["请问","这个行李箱","多少钱？"],"vi":"Xin hỏi chiếc va li này giá bao nhiêu?"},{"chunks":["如果","你买满两百元","就可以","获得一本词典。"],"vi":"Nếu bạn mua đủ hai trăm tệ thì có thể nhận một cuốn từ điển."},{"chunks":["春天来了","冬天的衣服","就会打折。"],"vi":"Xuân đến rồi thì quần áo mùa đông sẽ được giảm giá."},{"chunks":["为了感谢","顾客的支持","我们","举行了这次活动。"],"vi":"Để cảm ơn sự ủng hộ của khách hàng, chúng tôi đã tổ chức hoạt động lần này."}],"read":{"text":"周末，我和朋友去书店买书。书店在举行活动，所有图书都打八折，买满一百元还可以免费得到一个笔记本。我本来只想买一本词典，后来看到很多有意思的小说，也买了几本。朋友说，打折的东西不一定都好，要先考虑自己是不是真的需要。回家以后我发现，有两本小说我其实不太喜欢，真不应该买。","vi":"Cuối tuần, tôi và bạn đến một hiệu sách mua sách. Hiệu sách đang tổ chức hoạt động, tất cả sách đều giảm 20%, mua đủ 100 tệ còn được tặng miễn phí một cuốn sổ. Tôi vốn chỉ định mua một cuốn từ điển, sau đó thấy nhiều cuốn tiểu thuyết thú vị nên mỗi loại mua mấy cuốn. Bạn nói đồ giảm giá chưa chắc đã tốt, phải cân nhắc xem mình có thật sự cần không. Về nhà tôi mới nhận ra có hai cuốn tiểu thuyết thật ra tôi không thích lắm, không nên mua.","qs":[{"q":"书店的活动是什么？","opts":["图书打八折，买满一百元送笔记本","所有图书免费","买词典送小说","买满一百元打五折"],"a":0,"exp":"Bài nói tất cả sách giảm 20% (打八折) và mua đủ 100 tệ thì được tặng một quyển sổ tay, nên chọn đáp án đầu; sách không miễn phí, không tặng từ điển, cũng không giảm một nửa."},{"q":"朋友的意思是什么？","opts":["打折的东西都很好","不要在书店买书","打折的东西不一定都好，要看自己是否需要","小说比词典好"],"a":2,"exp":"Người bạn nói “打折的东西不一定都好”, phải xem mình có thật sự cần không, khớp với đáp án đúng. “Đồ giảm giá đều tốt” ngược ý bạn; hai đáp án còn lại không được nói đến."},{"q":"回家以后，“我”发现了什么？","opts":["词典买错了","有些小说不是自己喜欢的，不该买","笔记本坏了","钱不够"],"a":1,"exp":"Câu cuối nói có hai cuốn tiểu thuyết thật ra không thích lắm, 真不应该买 (lẽ ra không nên mua), nên đáp án là có vài cuốn tiểu thuyết không hợp sở thích, không nên mua; các đáp án khác không có trong bài."}]},"write":[{"word":"免费","hint":"Nói rằng ly cà phê đầu tiên của quán này được miễn phí.","model":"这家咖啡店的第一杯咖啡是免费的。","py":"Zhè jiā kāfēi diàn de dì-yī bēi kāfēi shì miǎnfèi de.","vi":"Ly cà phê đầu tiên của quán cà phê này được miễn phí."},{"word":"值得","hint":"Nói với bạn rằng cuốn tiểu thuyết này hay, đáng để đọc.","model":"这本小说很有意思，值得你看一看。","py":"Zhè běn xiǎoshuō hěn yǒuyìsi, zhíde nǐ kàn yi kàn.","vi":"Cuốn tiểu thuyết này rất thú vị, đáng để bạn đọc thử."},{"word":"感谢","hint":"Cảm ơn mọi người hôm nay đến dự tiệc sinh nhật của bạn.","model":"感谢大家今天来参加我的生日会。","py":"Gǎnxiè dàjiā jīntiān lái cānjiā wǒ de shēngrì huì.","vi":"Cảm ơn mọi người hôm nay đã đến dự tiệc sinh nhật của tôi."}]},"7":{"fill":[{"q":"天气忽冷忽热的时候，人特别____感冒。","opts":["严重","辛苦","容易","幸福"],"a":2,"exp":"Đáp án 容易 (dễ): “容易 + động từ” nghĩa là dễ xảy ra, “容易感冒” là cách nói quen thuộc. 严重 (nghiêm trọng), 辛苦 (vất vả), 幸福 (hạnh phúc) không đi với 感冒 như vậy."},{"q":"医生说你的病不____，休息几天就会好。","opts":["重要","严重","幸福","辛苦"],"a":1,"exp":"“病不严重” nghĩa là bệnh không nặng (严重 = nghiêm trọng), khớp với vế sau “nghỉ vài ngày sẽ khỏi”. 重要 (quan trọng), 幸福 (hạnh phúc), 辛苦 (vất vả) không dùng để nói về bệnh."},{"q":"你要多____身体，别总是睡得太晚。","opts":["同意","希望","认为","注意"],"a":3,"exp":"“注意身体” (chú ý giữ gìn sức khỏe) là cụm cố định, hợp với vế sau “đừng thức khuya”. 同意 (đồng ý), 希望 (hy vọng), 认为 (cho rằng) không đi với 身体."},{"q":"他每天晚上都去公园____一个小时，所以身体很好。","opts":["锻炼","理解","后悔","同意"],"a":0,"exp":"锻炼 (tập luyện) là vận động để khỏe người, chỉ từ này hợp với “mỗi tối ra công viên … một tiếng, nên sức khỏe tốt”; 理解 (hiểu), 后悔 (hối hận), 同意 (đồng ý) không hợp."},{"q":"要是现在不努力，以后你一定会____的。","opts":["同意","后悔","减肥","散步"],"a":1,"exp":"Đáp án 后悔 (hối hận): “bây giờ không cố gắng thì sau này sẽ hối hận” là cách nói thông dụng. 同意 (đồng ý), 减肥 (giảm cân), 散步 (đi dạo) không hợp nghĩa."},{"q":"孩子刚上学，爸爸妈妈有点儿____他在学校吃不好。","opts":["希望","理解","担心","同意"],"a":2,"exp":"“担心” (lo lắng) đi với điều không tốt có thể xảy ra, ở đây là “ăn không ngon ở trường”. 希望 (hy vọng), 理解 (thấu hiểu), 同意 (đồng ý) không hợp với việc xấu này."}],"order":[{"chunks":["医生让我","以后不要","再抽烟了。"],"vi":"Bác sĩ bảo tôi sau này đừng hút thuốc nữa."},{"chunks":["长时间看电脑","对眼睛","不太好。"],"vi":"Nhìn máy tính trong thời gian dài không tốt lắm cho mắt."},{"chunks":["他不但","喜欢跑步","而且","喜欢散步。"],"vi":"Anh ấy không những thích chạy bộ mà còn thích đi dạo."},{"chunks":["只有经常锻炼","身体才","会健康。"],"vi":"Chỉ có thường xuyên tập luyện thì cơ thể mới khỏe mạnh."}],"read":{"text":"我的邻居王大爷今年七十岁了，身体一直很好。他有一个习惯：每天早上六点起床，先在小区里走半个小时，然后回家吃早饭。以前他不太爱运动，后来因为感冒了一个多月，才明白身体最重要。现在他不但自己天天散步，还常常叫邻居们一起去。他说，吃药不如多活动，心情好了，病也会少一些。","vi":"Ông Vương hàng xóm của tôi năm nay bảy mươi tuổi, sức khỏe luôn rất tốt. Ông có một thói quen: sáng nào cũng sáu giờ dậy, đầu tiên đi bộ nửa tiếng trong khu dân cư, rồi mới về nhà ăn sáng. Trước đây ông không thích vận động lắm, sau này vì bị cảm hơn một tháng nên mới hiểu sức khỏe là quan trọng nhất. Bây giờ ông không những tự mình ngày nào cũng đi dạo mà còn thường rủ hàng xóm cùng đi. Ông nói uống thuốc không bằng vận động nhiều, tâm trạng tốt thì bệnh cũng ít đi.","qs":[{"q":"王大爷为什么开始每天散步？","opts":["医生让他每天走路","他感冒很久以后明白了健康的重要","邻居们都请他去","他想要减肥"],"a":1,"exp":"Bài viết nói ông bị cảm hơn một tháng rồi mới hiểu sức khỏe quan trọng nhất nên bắt đầu đi dạo, khớp đáp án B. Bác sĩ bảo, hàng xóm mời hay muốn giảm cân đều không có trong bài (hàng xóm là người ông rủ về sau)."},{"q":"下面哪句话符合短文的意思？","opts":["王大爷年轻时就爱运动","王大爷只自己一个人散步","王大爷散步以后才吃早饭","王大爷觉得吃药比运动重要"],"a":2,"exp":"Bài nói ông “đi bộ nửa tiếng trước, rồi mới về nhà ăn sáng”, tức là đi dạo xong mới ăn sáng; ba đáp án còn lại (hồi trẻ thích vận động, đi một mình, uống thuốc quan trọng hơn) đều trái với bài."},{"q":"王大爷认为怎样可以少生病？","opts":["多吃药","少和邻居说话","早点儿睡觉","多活动，心情好"],"a":3,"exp":"Đáp án 多活动，心情好: ông Vương nói “uống thuốc không bằng vận động nhiều, tâm trạng tốt thì bệnh cũng ít đi”, nên các đáp án uống thuốc nhiều hay ít nói chuyện đều sai."}]},"write":[{"word":"影响","hint":"Nói rằng ngủ quá muộn sẽ ảnh hưởng đến sức khỏe.","model":"睡得太晚会影响身体健康。","py":"Shuì de tài wǎn huì yǐngxiǎng shēntǐ jiànkāng.","vi":"Ngủ quá muộn sẽ ảnh hưởng đến sức khỏe."},{"word":"减肥","hint":"Nói bạn của bạn muốn giảm cân nên tối nào cũng đi chạy bộ.","model":"我朋友想减肥，每天晚上都去跑步。","py":"Wǒ péngyou xiǎng jiǎnféi, měi tiān wǎnshang dōu qù pǎobù.","vi":"Bạn tôi muốn giảm cân, tối nào cũng đi chạy bộ."},{"word":"需要","hint":"Nói khi bị bệnh, chúng ta cần nghỉ ngơi nhiều và uống nhiều nước.","model":"生病的时候，我们需要多休息，多喝水。","py":"Shēngbìng de shíhou, wǒmen xūyào duō xiūxi, duō hē shuǐ.","vi":"Khi bị bệnh, chúng ta cần nghỉ ngơi nhiều và uống nhiều nước."}]},"8":{"fill":[{"q":"图书馆里很____，大家都在认真看书。","opts":["伤心","安静","浪漫","缺少"],"a":1,"exp":"Mọi người chăm chú đọc sách nên thư viện phải 安静 (yên tĩnh). 伤心 (buồn) và 浪漫 (lãng mạn) không hợp ngữ cảnh, còn 缺少 (thiếu) là động từ nên không đứng sau “很” theo cách này."},{"q":"你喜欢哪种____的衣服？红色的还是白色的？","opts":["态度","性格","颜色","礼物"],"a":2,"exp":"“红色、白色” đều là 颜色 (màu sắc), nên hỏi “哪种颜色的衣服”. 态度 (thái độ), 性格 (tính cách), 礼物 (quà) không dùng để miêu tả màu áo."},{"q":"这两个房间都不错，你想____哪一个？","opts":["选择","改变","缺少","证明"],"a":0,"exp":"Chọn một trong hai căn phòng thì dùng 选择 (lựa chọn), đi được với “哪一个”; 改变 (thay đổi), 缺少 (thiếu), 证明 (chứng minh) không mang nghĩa chọn."},{"q":"他说话的____很好，对谁都很热情。","opts":["压力","颜色","礼物","态度"],"a":3,"exp":"Đáp án 态度 (thái độ): “说话的态度很好” khớp với việc đối với ai cũng nhiệt tình. 压力 (áp lực), 颜色 (màu sắc), 礼物 (quà) không đi với 说话."},{"q":"这个城市什么都有，就是____公园。","opts":["改变","缺少","证明","得到"],"a":1,"exp":"“什么都有，就是缺少公园” nghĩa là thành phố có đủ thứ, chỉ thiếu công viên; 缺少 = thiếu. 改变 (thay đổi), 证明 (chứng minh), 得到 (đạt được) trái nghĩa hoặc không hợp câu."},{"q":"老师说，考试以前不要给自己太大的____。","opts":["颜色","办法","压力","礼物"],"a":2,"exp":"“给自己压力” (tự tạo áp lực) là cách nói quen thuộc, “太大的压力” cũng tự nhiên. 颜色 (màu), 办法 (cách), 礼物 (quà) không đi với “太大的”."}],"order":[{"chunks":["红色让人","变得","很热情。"],"vi":"Màu đỏ khiến con người trở nên rất nhiệt tình."},{"chunks":["遇到烦恼时","你应该","想一些办法","改变心情。"],"vi":"Khi gặp phiền muộn, bạn nên nghĩ vài cách để thay đổi tâm trạng."},{"chunks":["女孩子","往往","喜欢","穿白色的衣服。"],"vi":"Các cô gái thường thích mặc quần áo màu trắng."},{"chunks":["只要你","有耐心","就能","把事情做好。"],"vi":"Chỉ cần bạn có kiên nhẫn thì có thể làm tốt mọi việc."}],"read":{"text":"小美最近工作压力很大，心情一直不太好。朋友送给她一件黄色的衣服，说黄色可以让人心情愉快。小美本来不喜欢黄色，觉得自己穿不好看。可是第二天她穿着这件衣服去上班，同事们都说她看上去很有精神。那天下班以后，她心情好了很多，还请同事们一起吃饭。她终于明白，换一种颜色，有时也能换来一种好心情。","vi":"Gần đây Tiểu Mỹ áp lực công việc rất lớn, tâm trạng luôn không tốt. Bạn tặng cô một chiếc áo màu vàng, nói rằng màu vàng có thể làm người ta vui vẻ. Vốn dĩ Tiểu Mỹ không thích màu vàng, cảm thấy mình mặc không đẹp. Nhưng hôm sau cô mặc chiếc áo này đi làm, đồng nghiệp đều nói trông cô rất có tinh thần. Sau khi tan làm hôm đó, tâm trạng cô tốt lên rất nhiều, còn mời đồng nghiệp cùng đi ăn cơm. Cuối cùng cô hiểu ra rằng, đổi một màu sắc đôi khi cũng có thể đổi được một tâm trạng tốt.","qs":[{"q":"小美最近为什么心情不好？","opts":["她不喜欢黄色","朋友没有送她礼物","工作压力很大","同事们不喜欢她"],"a":2,"exp":"Câu đầu bài nói rõ Tiểu Mỹ dạo này 工作压力很大 (áp lực công việc lớn) nên tâm trạng không tốt; không thích màu vàng chỉ là chuyện về sau, còn bạn có tặng quà và đồng nghiệp đều khen cô ấy."},{"q":"小美穿黄色衣服以前是怎么想的？","opts":["她觉得自己穿不好看","她觉得黄色最漂亮","她想把衣服送给同事","她担心上班会迟到"],"a":0,"exp":"Đáp án 她觉得自己穿不好看: bài viết nói cô vốn không thích màu vàng và nghĩ mình mặc không đẹp. Các đáp án khác không được nhắc tới."},{"q":"这段话主要想说明什么？","opts":["黄色比别的颜色便宜","同事们都爱请客","工作比心情重要","颜色有时能改变人的心情"],"a":3,"exp":"Câu cuối nói đổi một màu sắc đôi khi cũng đổi được tâm trạng tốt, đó là ý chính: 颜色有时能改变人的心情. Các đáp án khác (màu vàng rẻ hơn, đồng nghiệp thích mời khách, công việc quan trọng hơn tâm trạng) không được bài nói tới."}]},"write":[{"word":"选择","hint":"Nói bạn đã chọn màu xanh lam vì nó khiến bạn cảm thấy rất thoải mái.","model":"我选择了蓝色，因为蓝色让我觉得很舒服。","py":"Wǒ xuǎnzé le lánsè, yīnwèi lánsè ràng wǒ juéde hěn shūfu.","vi":"Tôi đã chọn màu xanh lam vì màu xanh lam khiến tôi cảm thấy rất thoải mái."},{"word":"改变","hint":"Nói chúng ta không thể thay đổi thời tiết nhưng có thể thay đổi tâm trạng của mình.","model":"我们改变不了天气，但是可以改变自己的心情。","py":"Wǒmen gǎibiàn bùliǎo tiānqì, dànshì kěyǐ gǎibiàn zìjǐ de xīnqíng.","vi":"Chúng ta không thể thay đổi thời tiết, nhưng có thể thay đổi tâm trạng của chính mình."},{"word":"遇到","hint":"Khuyên người khác: nếu gặp phiền muộn thì nghe nhạc để thư giãn.","model":"如果你遇到烦恼，可以听听音乐，放松一下。","py":"Rúguǒ nǐ yùdào fánnǎo, kěyǐ tīngting yīnyuè, fàngsōng yíxià.","vi":"Nếu bạn gặp phiền muộn, có thể nghe nhạc để thư giãn một chút."}]},"9":{"fill":[{"q":"他第一次开饭馆就____了，可是他没有放弃，继续努力。","opts":["成功","担心","失败","考虑"],"a":2,"exp":"Sau “可是他没有放弃” là kết quả không tốt, nên dùng 失败 (thất bại)."},{"q":"____下大雨，我们也要按时出发。","opts":["因为","即使","所以","可是"],"a":1,"exp":"“即使……也……” diễn tả nhượng bộ: cho dù … cũng …"},{"q":"遇到问题要想办法____，不能只是抱怨。","opts":["放弃","总结","担心","解决"],"a":3,"exp":"“解决问题” là cách kết hợp cố định (giải quyết vấn đề); các từ còn lại không hợp nghĩa."},{"q":"他学汉语的____很丰富，经常给同学介绍好方法。","opts":["烦恼","区别","经验","态度"],"a":2,"exp":"“经验丰富” là cụm quen thuộc (giàu kinh nghiệm); 烦恼, 区别, 态度 không đi với 丰富."},{"q":"面对失败，他的____很积极，一点儿也不难过。","opts":["过程","材料","区别","态度"],"a":3,"exp":"“态度积极” (thái độ tích cực) hợp nghĩa; các từ còn lại không thể gọi là “积极”."},{"q":"我想____一下再回答你，现在还不能决定。","opts":["考虑","坚持","面对","经历"],"a":0,"exp":"“考虑一下再回答” nghĩa là cân nhắc rồi mới trả lời, khớp với “现在还不能决定”."}],"order":[{"chunks":["只要","坚持下去","就一定会","成功。"],"vi":"Chỉ cần kiên trì tiếp tục thì nhất định sẽ thành công."},{"chunks":["我们","应该","把注意力","放在过程上。"],"vi":"Chúng ta nên đặt sự chú ý vào quá trình."},{"chunks":["即使","结果不好","至少","我努力过。"],"vi":"Cho dù kết quả không tốt, ít nhất tôi đã nỗ lực."},{"chunks":["他在失败中","总结出了","很多","有用的经验。"],"vi":"Anh ấy đã rút ra được nhiều kinh nghiệm hữu ích từ thất bại."}],"read":{"text":"小周去年开始学游泳。第一次下水时，他很担心，不敢把头放进水里。朋友们说太难了，让他别学了。可是小周没有同意，每个周末都去游泳馆练习，遇到问题就问教练。三个月后，他终于能游五十米了。他说，学游泳的过程虽然很辛苦，但他明白了一件事：只要不放弃，困难就会慢慢变小。","vi":"Năm ngoái tiểu Chu bắt đầu học bơi. Lần đầu xuống nước, anh rất lo, không dám cho đầu xuống nước. Bạn bè nói quá khó, bảo anh đừng học nữa. Nhưng tiểu Chu không đồng ý, cuối tuần nào cũng đến bể bơi luyện tập, gặp vấn đề thì hỏi huấn luyện viên. Ba tháng sau, anh cuối cùng đã bơi được năm mươi mét. Anh nói, quá trình học bơi tuy rất vất vả, nhưng anh hiểu ra một điều: chỉ cần không từ bỏ, khó khăn sẽ dần dần nhỏ đi.","qs":[{"q":"朋友们对小周学游泳是什么看法？","opts":["都很支持他","觉得太难，不赞成","想和他一起学","一点儿也不关心"],"a":1,"exp":"Bài viết: bạn bè “说太难了，让他别学了” nên là không tán thành."},{"q":"小周是怎么练习游泳的？","opts":["每天晚上都去游泳","只在放假的时候去","每周末都去，有问题就问教练","请朋友在家里教他"],"a":2,"exp":"Bài viết: “每个周末都去游泳馆练习，遇到问题就问教练”."},{"q":"这段话最想告诉我们什么？","opts":["只要不放弃，困难会慢慢变小","学游泳比别的运动容易","学习时一定要听朋友的话","三个月就能学会所有东西"],"a":0,"exp":"Câu cuối nêu ý chính: chỉ cần không từ bỏ, khó khăn sẽ nhỏ dần."}]},"write":[{"word":"勇敢","hint":"Nói bạn của bạn rất dũng cảm, dám nói thật.","model":"我的朋友很勇敢，敢说真话。","py":"Wǒ de péngyou hěn yǒnggǎn, gǎn shuō zhēnhuà.","vi":"Bạn của tôi rất dũng cảm, dám nói lời thật."},{"word":"放弃","hint":"Dù khó đến đâu cũng không từ bỏ ước mơ của mình.","model":"不管多难，我也不会放弃自己的理想。","py":"Bùguǎn duō nán, wǒ yě bú huì fàngqì zìjǐ de lǐxiǎng.","vi":"Dù khó đến đâu, tôi cũng sẽ không từ bỏ lý tưởng của mình."},{"word":"积累","hint":"Mỗi ngày nhớ vài từ mới, lâu dần sẽ tích lũy được nhiều từ vựng.","model":"每天记几个生词，时间长了就能积累很多词语。","py":"Měi tiān jì jǐ gè shēngcí, shíjiān cháng le jiù néng jīlěi hěn duō cíyǔ.","vi":"Mỗi ngày nhớ vài từ mới, lâu dần sẽ tích lũy được nhiều từ ngữ."}]},"10":{"fill":[{"q":"他的____很高，所以每个月都能存下不少钱。","opts":["感情","工资","方面","压力"],"a":1,"exp":"Có thể tiết kiệm được tiền vì 工资 (lương) cao; các từ khác không hợp nghĩa."},{"q":"我很____他，他的工作轻松，收入又高。","opts":["照顾","理解","羡慕","保证"],"a":2,"exp":"Vế sau nói điều kiện của anh ta tốt, nên người nói ngưỡng mộ: 羡慕."},{"q":"孩子生病了，要____送他去医院。","opts":["特别","永远","真正","及时"],"a":3,"exp":"及时 nghĩa là kịp thời, hợp với việc con ốm phải đưa đi bệnh viện ngay."},{"q":"____工作很忙，她最近没有时间陪孩子。","opts":["由于","例如","虽然","不管"],"a":0,"exp":"Vế trước là nguyên nhân, vế sau là kết quả nên dùng 由于; 虽然 cần vế sau có 但是."},{"q":"周末去爬山能让人____心情，忘掉工作的压力。","opts":["决定","保证","放松","需要"],"a":2,"exp":"“放松心情” là cụm cố định: thư giãn tinh thần."},{"q":"对一个公司来说，找到好员工是成功的____。","opts":["经济","关键","生活","方面"],"a":1,"exp":"“成功的关键” nghĩa là chìa khóa của thành công; các từ khác không hợp."}],"order":[{"chunks":["除了","工作以外","他还要","照顾家人。"],"vi":"Ngoài công việc ra, anh ấy còn phải chăm sóc gia đình."},{"chunks":["我们","应该","理解","别人的","选择。"],"vi":"Chúng ta nên thông cảm với lựa chọn của người khác."},{"chunks":["如果","没钱","很难","过得幸福。"],"vi":"Nếu không có tiền thì rất khó sống hạnh phúc."},{"chunks":["小时候","得到一块糖","就觉得","很幸福。"],"vi":"Lúc nhỏ, có được một viên kẹo là thấy rất hạnh phúc."}],"read":{"text":"小李毕业后进了一家大公司，工资很高，朋友们都很羡慕他。可是他每天工作十二个小时，没时间陪家人，身体也越来越差。后来他换了一份工作，收入比以前少了一半，但是可以准时下班，周末还能和妻子去公园散步。他说，现在才知道，对自己来说，幸福就是有时间做喜欢的事。","vi":"Sau khi tốt nghiệp, tiểu Lý vào một công ty lớn, lương rất cao, bạn bè đều ngưỡng mộ anh. Nhưng mỗi ngày anh làm việc mười hai tiếng, không có thời gian bên gia đình, sức khỏe cũng ngày càng kém. Sau đó anh đổi sang công việc khác, thu nhập ít hơn trước một nửa, nhưng có thể tan làm đúng giờ, cuối tuần còn cùng vợ đi dạo công viên. Anh nói, bây giờ mới biết, với anh hạnh phúc là có thời gian làm việc mình thích.","qs":[{"q":"朋友们为什么羡慕小李？","opts":["他的工作很轻松","他住在公园旁边","他在大公司工作，工资高","他常常陪家人"],"a":2,"exp":"Bài viết: “进了一家大公司，工资很高，朋友们都很羡慕他”."},{"q":"换工作以后，小李的生活有什么变化？","opts":["收入和时间都变多了","收入少了，但有了更多自己的时间","收入更高，但是更忙了","什么都没有变"],"a":1,"exp":"Thu nhập “少了一半” nhưng tan làm đúng giờ, cuối tuần rảnh, nghĩa là có nhiều thời gian hơn."},{"q":"下面哪一句最接近这段话的意思？","opts":["工资越高越幸福","换工作是很容易的事","妻子比朋友更重要","幸福不只是钱，也要有自己的时间"],"a":3,"exp":"Cuối bài anh nói hạnh phúc là có thời gian làm điều mình thích, tức là không chỉ dựa vào tiền."}]},"write":[{"word":"例如","hint":"Nói có những thứ tiền không mua được, ví dụ tình cảm và thời gian.","model":"有些东西用钱买不到，例如感情和时间。","py":"Yǒuxiē dōngxi yòng qián mǎi bú dào, lìrú gǎnqíng hé shíjiān.","vi":"Có những thứ không mua được bằng tiền, ví dụ như tình cảm và thời gian."},{"word":"压力","hint":"Gần đây áp lực công việc lớn, tối thường ngủ không ngon.","model":"最近工作压力很大，我晚上常常睡不好。","py":"Zuìjìn gōngzuò yālì hěn dà, wǒ wǎnshang chángcháng shuì bù hǎo.","vi":"Gần đây áp lực công việc rất lớn, buổi tối tôi thường ngủ không ngon."},{"word":"决定","hint":"Nói bạn quyết định từ tháng sau mỗi ngày tập thể dục.","model":"我决定下个月开始每天锻炼身体。","py":"Wǒ juédìng xià ge yuè kāishǐ měi tiān duànliàn shēntǐ.","vi":"Tôi quyết định từ tháng sau bắt đầu tập thể dục mỗi ngày."}]},"11":{"fill":[{"q":"他每天晚上都____跑步，所以身体越来越好。","opts":["坚持","放弃","判断","增加"],"a":0,"exp":"“坚持跑步” là kiên trì chạy bộ, hợp với vế sau “身体越来越好”; 放弃 (từ bỏ) trái nghĩa, 判断/增加 không đi với 跑步."},{"q":"小时候父母就教我早睡早起，现在我已经____了这个好习惯。","opts":["提高","养成","丰富","减轻"],"a":1,"exp":"“养成习惯” là cụm cố định: hình thành thói quen."},{"q":"最近工作太忙，我的____很大，晚上常常睡不着。","opts":["顺序","看法","压力","好处"],"a":2,"exp":"“压力很大” (áp lực lớn) hợp với việc công việc bận và khó ngủ."},{"q":"要想____汉语水平，就得多听、多说、多读。","opts":["减轻","放弃","判断","提高"],"a":3,"exp":"“提高水平” là cụm cố định: nâng cao trình độ."},{"q":"做这道菜的时候，____要把菜洗干净，其次才是切。","opts":["最后","然而","首先","否则"],"a":2,"exp":"“首先……其次……” dùng để liệt kê thứ tự; vế sau có 其次 nên vế đầu là 首先."},{"q":"昨天的足球比赛非常____，大家看得都很高兴。","opts":["有限","相同","困难","精彩"],"a":3,"exp":"精彩 (đặc sắc) dùng để khen trận đấu hay; các từ còn lại không hợp nghĩa."}],"order":[{"chunks":["根据","这次调查","年轻人","每天都看手机。"],"vi":"Theo cuộc khảo sát lần này, người trẻ ngày nào cũng xem điện thoại."},{"chunks":["读书","可以","减轻","我们的压力。"],"vi":"Đọc sách có thể làm giảm áp lực của chúng ta."},{"chunks":["他","把","喜欢的句子","记在本子上。"],"vi":"Anh ấy ghi những câu mình thích vào quyển vở."},{"chunks":["无论","工作多忙，","他都","坚持阅读。"],"vi":"Dù công việc bận đến đâu, anh ấy cũng kiên trì đọc sách."}],"read":{"text":"小王以前不爱看书，一拿起书就想睡觉。后来他听了朋友的建议，每天晚上只读十分钟，还把喜欢的句子写在本子上。刚开始他觉得很难坚持，但是三个月以后，他发现自己已经养成了阅读的习惯。他说，读书最重要的不是读得多，而是每天都读。","vi":"Trước đây Tiểu Vương không thích đọc sách, cứ cầm sách lên là buồn ngủ. Sau đó anh nghe theo lời khuyên của bạn, mỗi tối chỉ đọc mười phút, còn chép những câu mình thích vào quyển vở. Lúc đầu anh thấy rất khó kiên trì, nhưng ba tháng sau, anh nhận ra mình đã hình thành thói quen đọc sách. Anh nói, điều quan trọng nhất khi đọc sách không phải là đọc nhiều, mà là ngày nào cũng đọc.","qs":[{"q":"小王是怎么开始读书的？","opts":["老师要求他每天读一本书","他听朋友的建议，每天读一点儿","他想找一份新工作","他想睡得更好"],"a":1,"exp":"Đoạn văn nói anh nghe theo lời khuyên của bạn và mỗi tối chỉ đọc mười phút."},{"q":"小王认为读书最重要的是什么？","opts":["读得很多","读得很快","买很多书","每天坚持读"],"a":3,"exp":"Anh nói quan trọng không phải đọc nhiều mà là ngày nào cũng đọc, tức là kiên trì mỗi ngày."},{"q":"三个月以后，小王有什么变化？","opts":["已经习惯了每天阅读","不再看书了","换了新朋友","开始写书了"],"a":0,"exp":"“养成了阅读的习惯” nghĩa là đã quen với việc đọc sách mỗi ngày."}]},"write":[{"word":"放弃","hint":"Nói rằng dù khó đến đâu bạn cũng sẽ không từ bỏ việc học tiếng Trung.","model":"不管多难，我都不会放弃学习汉语。","py":"Bùguǎn duō nán, wǒ dōu bú huì fàngqì xuéxí Hànyǔ.","vi":"Dù khó đến đâu, tôi cũng sẽ không từ bỏ việc học tiếng Trung."},{"word":"复习","hint":"Nói rằng trước kỳ thi bạn phải ôn lại những từ đã học.","model":"考试以前，我要把学过的词语再复习一遍。","py":"Kǎoshì yǐqián, wǒ yào bǎ xuéguo de cíyǔ zài fùxí yí biàn.","vi":"Trước khi thi, tôi phải ôn lại một lượt những từ đã học."},{"word":"丰富","hint":"Nói rằng đi du lịch có thể làm cuộc sống của chúng ta phong phú hơn.","model":"旅行可以丰富我们的生活。","py":"Lǚxíng kěyǐ fēngfù wǒmen de shēnghuó.","vi":"Du lịch có thể làm phong phú cuộc sống của chúng ta."}]},"12":{"fill":[{"q":"每个人都有优点，也都有____，我们要学会接受。","opts":["效果","语言","缺点","任务"],"a":2,"exp":"Đối lập với 优点 (ưu điểm) là 缺点 (khuyết điểm)."},{"q":"我不是那个意思，你____我了。","opts":["误会","节约","适合","达到"],"a":0,"exp":"“误会我了” nghĩa là hiểu lầm tôi; các từ còn lại không đi với 我 theo nghĩa này."},{"q":"天气太热了，我们应该____用电，不要浪费。","opts":["引起","指出","达到","节约"],"a":3,"exp":"“节约用电” là tiết kiệm điện, hợp với vế sau “不要浪费”."},{"q":"这件衣服颜色很好看，但是不太____我，有点儿小。","opts":["保护","适合","了解","总结"],"a":1,"exp":"“不适合我” là không hợp với tôi (quá nhỏ); các từ khác không hợp nghĩa."},{"q":"他____自己的努力，终于考上了理想的大学。","opts":["根据","对于","通过","尤其"],"a":2,"exp":"“通过努力” nghĩa là nhờ nỗ lực; 根据/对于 không hợp, 尤其 là phó từ không đứng ở vị trí này."},{"q":"我喜欢各种水果，____是西瓜。","opts":["尤其","往往","直接","仔细"],"a":0,"exp":"“尤其是……” nghĩa là đặc biệt là…, dùng để nhấn mạnh một thứ trong số nhiều thứ."}],"order":[{"chunks":["老师","仔细地","解释了","这个问题。"],"vi":"Thầy giáo giải thích kỹ vấn đề này."},{"chunks":["他","通过","朋友","了解到这件事。"],"vi":"Anh ấy biết được chuyện này thông qua bạn bè."},{"chunks":["妈妈","提醒","我","早点儿睡觉。"],"vi":"Mẹ nhắc tôi đi ngủ sớm một chút."},{"chunks":["我","觉得","这个方法","不适合他。"],"vi":"Tôi thấy cách này không phù hợp với anh ấy."}],"read":{"text":"小李和小张都在学英语。小李每天花三个小时背单词，但是效果不太好。小张先听了别人的意见，再根据自己的情况，选择了看电影的方法，每天只学一个小时，进步却很快。小张说：别人的方法不一定适合自己，要仔细想一想，才会有效果。","vi":"Tiểu Lý và Tiểu Trương đều đang học tiếng Anh. Mỗi ngày Tiểu Lý dành ba tiếng học từ vựng nhưng hiệu quả không tốt lắm. Tiểu Trương trước hết nghe ý kiến của người khác, rồi dựa vào tình hình của bản thân, chọn cách xem phim, mỗi ngày chỉ học một tiếng mà tiến bộ lại rất nhanh. Tiểu Trương nói: cách của người khác chưa chắc đã hợp với mình, phải suy nghĩ kỹ thì mới có hiệu quả.","qs":[{"q":"小张为什么进步很快？","opts":["他每天学习三个小时","他的英语本来就很好","他不听别人的意见","他选了适合自己的学习方法"],"a":3,"exp":"Tiểu Trương dựa vào tình hình của mình để chọn cách học phù hợp (xem phim), nên học ít mà vẫn tiến bộ nhanh."},{"q":"关于小李，下面哪句话是对的？","opts":["他每天花很多时间，但效果不太好","他常常看电影学英语","他学习的时间比小张短","他不想进步"],"a":0,"exp":"Tiểu Lý mỗi ngày học ba tiếng, nhiều hơn Tiểu Trương, nhưng hiệu quả không tốt."},{"q":"这段话主要想告诉我们什么？","opts":["学英语一定要看电影","学习方法要适合自己","学习时间越长越好","别人的方法都不好"],"a":1,"exp":"Ý chính nằm ở lời Tiểu Trương: cách của người khác chưa chắc hợp với mình, phải suy nghĩ để chọn cách phù hợp với bản thân."}]},"write":[{"word":"提醒","hint":"Nhờ bạn mình ngày mai nhắc bạn mang từ điển.","model":"请你明天提醒我带词典。","py":"Qǐng nǐ míngtiān tíxǐng wǒ dài cídiǎn.","vi":"Phiền bạn ngày mai nhắc tôi mang từ điển."},{"word":"直接","hint":"Khuyên rằng khi có vấn đề thì tốt nhất nên nói thẳng với anh ấy.","model":"有问题的时候，最好直接告诉他。","py":"Yǒu wèntí de shíhou, zuìhǎo zhíjiē gàosu tā.","vi":"Khi có vấn đề, tốt nhất là nói thẳng với anh ấy."},{"word":"保护","hint":"Nói rằng chúng ta nên bảo vệ môi trường.","model":"我们应该保护环境。","py":"Wǒmen yīnggāi bǎohù huánjìng.","vi":"Chúng ta nên bảo vệ môi trường."}]},"13":{"fill":[{"q":"这家餐厅为外国客人____了叉子和筷子。","opts":["调查","缺少","提供","发现"],"a":2,"exp":"“提供”nghĩa là cung cấp, hợp với việc nhà hàng chuẩn bị dĩa và đũa cho khách."},{"q":"他用筷子的方法不太____，所以夹不起豆子。","opts":["解渴","正确","饮料","使用"],"a":1,"exp":"“方法不太正确”: cách dùng không đúng nên không gắp được; các từ còn lại không đi với “方法”."},{"q":"夏天很热，喝一杯冰茶最能____。","opts":["练习","缺少","使用","解渴"],"a":3,"exp":"“解渴” là giải khát, đúng với ngữ cảnh uống trà lạnh khi trời nóng."},{"q":"这道菜____咸了一点，下次少放点盐。","opts":["大约","稍微","好好","随着"],"a":1,"exp":"“稍微……一点” diễn tả mức độ nhẹ, đi với “咸了一点”."},{"q":"____时间的变化，越来越多的年轻人喜欢喝咖啡。","opts":["如果","所以","随着","虽然"],"a":2,"exp":"“随着……的变化” nghĩa là cùng với sự thay đổi của…, là cấu trúc cố định."},{"q":"在中国，喝茶是一个很____的习惯，几乎每个家庭都有茶叶。","opts":["缺少","专门","稍微","普遍"],"a":3,"exp":"“普遍” nghĩa là phổ biến, hợp với “几乎每个家庭”."}],"order":[{"chunks":["这家餐厅","为客人","提供","免费的茶。"],"vi":"Nhà hàng này cung cấp trà miễn phí cho khách."},{"chunks":["他","已经","学会了","用筷子。"],"vi":"Anh ấy đã học được cách dùng đũa."},{"chunks":["你","应该","好好","练习","发音。"],"vi":"Bạn nên luyện phát âm cho thật tốt."},{"chunks":["调查","发现","年轻人","更爱","喝咖啡。"],"vi":"Khảo sát cho thấy người trẻ thích uống cà phê hơn."}],"read":{"text":"我和朋友去一家中餐厅吃饭。朋友第一次来中国，不太会用筷子，夹菜时菜总是掉下来。服务员笑着给他拿来一把勺子，还教他怎么拿筷子。朋友练习了十几分钟，终于夹起了一块豆腐。他高兴地说：“原来用筷子并不难，只要多练习就行。”吃完饭，他还买了一双漂亮的筷子，打算送给爸爸。","vi":"Tôi cùng bạn đến một nhà hàng Trung Quốc ăn cơm. Bạn tôi lần đầu đến Trung Quốc, không biết dùng đũa lắm, lúc gắp thức ăn thì thức ăn cứ rơi xuống. Nhân viên cười và mang cho anh ấy một cái thìa, còn dạy anh ấy cách cầm đũa. Bạn tôi luyện tập hơn chục phút, cuối cùng đã gắp được một miếng đậu phụ. Anh ấy vui vẻ nói: “Hóa ra dùng đũa không khó, chỉ cần luyện tập nhiều là được.” Ăn xong, anh ấy còn mua một đôi đũa rất đẹp, định tặng cho bố.","qs":[{"q":"朋友夹菜时，菜为什么总是掉下来？","opts":["筷子太长了","他不太会用筷子","菜太热了","他不喜欢吃豆腐"],"a":1,"exp":"Đoạn văn nói “不太会用筷子”, nên thức ăn rơi."},{"q":"朋友最后对用筷子是什么看法？","opts":["很难，不想再学","没有勺子就吃不了","多练习就不难","只有中国人会用"],"a":2,"exp":"Anh ấy nói “原来用筷子并不难，只要多练习就行”."},{"q":"关于这位朋友，下面哪个说法是对的？","opts":["他以前常常用筷子","他想把筷子送给爸爸","服务员不愿意帮助他","他练习了一个多小时"],"a":1,"exp":"Cuối đoạn: mua đũa “打算送给自己的爸爸”."}]},"write":[{"word":"习惯","hint":"Nói rằng bạn đã quen dùng đũa để ăn cơm.","model":"我已经习惯用筷子吃饭了。","py":"Wǒ yǐjīng xíguàn yòng kuàizi chīfàn le.","vi":"Tôi đã quen ăn cơm bằng đũa rồi."},{"word":"提供","hint":"Nói quán trà cung cấp nước nóng miễn phí cho khách.","model":"这家茶馆为客人提供免费的热水。","py":"Zhè jiā cháguǎn wèi kèrén tígōng miǎnfèi de rèshuǐ.","vi":"Quán trà này cung cấp nước nóng miễn phí cho khách."},{"word":"当作","hint":"Nói nhiều người xem việc uống trà là một cách thư giãn.","model":"很多人把喝茶当作一种放松的方式。","py":"Hěn duō rén bǎ hē chá dàngzuò yì zhǒng fàngsōng de fāngshì.","vi":"Nhiều người xem việc uống trà là một cách thư giãn."}]},"14":{"fill":[{"q":"这家超市规定，顾客购物时塑料袋要付钱，不再____提供。","opts":["自备","免费","共同","降低"],"a":1,"exp":"“免费提供” là cung cấp miễn phí; “不再免费提供” khớp với quy định mới."},{"q":"为了____用电，我离开房间时总是随手关灯。","opts":["拒绝","鼓励","提醒","节约"],"a":3,"exp":"“节约用电” là tiết kiệm điện, hợp với việc tắt đèn."},{"q":"我们每个人都有____保护地球。","opts":["效果","作用","数量","责任"],"a":3,"exp":"“有责任做某事” là có trách nhiệm làm gì."},{"q":"老师常常____我们，出门要带自己的购物袋。","opts":["保证","减少","提醒","污染"],"a":2,"exp":"“提醒” là nhắc nhở, đi với nội dung lời dặn phía sau."},{"q":"城市里的空气污染越来越____，大家都开始担心。","opts":["严重","方便","共同","自备"],"a":0,"exp":"“污染越来越严重” là cách nói tự nhiên; các từ khác không hợp nghĩa."},{"q":"坐地铁比开车更环保，能有效____空气污染。","opts":["养成","减少","鼓励","乘坐"],"a":1,"exp":"“减少污染” là giảm ô nhiễm; “养成” dùng cho thói quen, “乘坐” cho phương tiện."}],"order":[{"chunks":["我们","应该","养成","节约用电的","好习惯。"],"vi":"Chúng ta nên hình thành thói quen tốt là tiết kiệm điện."},{"chunks":["商场","不再","为顾客","提供","免费塑料袋。"],"vi":"Trung tâm thương mại không còn cung cấp túi nhựa miễn phí cho khách."},{"chunks":["他","拒绝","使用","塑料袋。"],"vi":"Anh ấy từ chối dùng túi nhựa."},{"chunks":["坐地铁","不仅","方便，","而且","能减少污染。"],"vi":"Đi tàu điện ngầm không chỉ tiện mà còn giảm ô nhiễm."}],"read":{"text":"我住的小区以前垃圾很多。几位邻居开始了一个活动：大家把瓶子和纸放进蓝色的桶里。开始时，不少老人觉得很麻烦，总是忘记。于是年轻人每个周末都去帮忙，还给孩子们讲故事。三个月以后，小区变干净了，大家也慢慢养成了习惯。连小孩子都会提醒爷爷奶奶：“这个瓶子要放到蓝桶里！”","vi":"Khu dân cư tôi sống trước đây rác rất nhiều. Vài người hàng xóm bắt đầu một hoạt động: mọi người bỏ chai và giấy vào thùng màu xanh. Lúc đầu, không ít người già thấy phiền phức nên hay quên. Vì vậy người trẻ mỗi cuối tuần đều đến giúp, còn kể cho bọn trẻ những câu chuyện. Sau ba tháng, khu dân cư trở nên sạch sẽ, mọi người cũng dần hình thành thói quen. Ngay cả trẻ con cũng biết nhắc ông bà: “Cái chai này phải bỏ vào thùng xanh!”","qs":[{"q":"开始的时候，为什么有些老人做得不好？","opts":["他们不喜欢孩子","他们觉得麻烦，常常忘记","他们没有蓝色的桶","他们住得很远"],"a":1,"exp":"Đoạn văn: “觉得很麻烦，总是忘记”."},{"q":"年轻人是怎么帮助大家的？","opts":["每周末去帮忙并讲环保故事","给每家发钱","自己搬到别的小区","让老人别扔东西"],"a":0,"exp":"Bài viết nói người trẻ “每个周末都去帮忙，还给孩子们讲环保的小故事”, nên chọn đáp án A (cuối tuần đi giúp và kể chuyện bảo vệ môi trường). Phát tiền, chuyển đi, bảo người già đừng vứt đồ đều không có trong bài."},{"q":"最后一句话主要想说明什么？","opts":["孩子们喜欢蓝色","老人不愿意听孩子的话","小孩子也比老人更忙","好习惯已经养成，连孩子都会提醒大人"],"a":3,"exp":"Trẻ con còn nhắc ông bà, cho thấy thói quen đã hình thành trong cả khu."}]},"write":[{"word":"鼓励","hint":"Nói giáo viên khuyến khích học sinh tự mang bình nước đi học.","model":"老师鼓励学生自己带水杯上学。","py":"Lǎoshī gǔlì xuéshēng zìjǐ dài shuǐbēi shàngxué.","vi":"Giáo viên khuyến khích học sinh tự mang bình nước đến trường."},{"word":"保证","hint":"Hứa từ nay ra ngoài đều tự mang túi mua sắm.","model":"我保证以后出门都自备购物袋。","py":"Wǒ bǎozhèng yǐhòu chūmén dōu zìbèi gòuwù dài.","vi":"Tôi hứa sau này ra ngoài đều tự mang túi mua sắm."},{"word":"关注","hint":"Nói ngày càng nhiều người quan tâm đến vấn đề khí hậu nóng lên.","model":"越来越多的人开始关注气候变暖的问题。","py":"Yuè lái yuè duō de rén kāishǐ guānzhù qìhòu biànnuǎn de wèntí.","vi":"Ngày càng nhiều người bắt đầu quan tâm đến vấn đề khí hậu nóng lên."}]},"15":{"fill":[{"q":"老师发现小明的作文写得很好，就当着全班同学的面____了他。","opts":["批评","整理","表扬","怀疑"],"a":2,"exp":"Bài văn viết rất hay thì giáo viên sẽ 表扬 (khen ngợi) trước cả lớp; 批评 (phê bình), 怀疑 (nghi ngờ) trái với ngữ cảnh, còn 整理 (sắp xếp) không hợp với “当着全班同学的面”."},{"q":"孩子考试没考好，父母不应该生气，而应该____他，让他重新有信心。","opts":["骗","鼓励","批评","缺少"],"a":1,"exp":"Đáp án 鼓励 (khích lệ): vế sau “để con có lại sự tự tin” cho thấy cha mẹ nên khích lệ. 骗 (lừa), 批评 (phê bình), 缺少 (thiếu) trái ý hoặc không hợp."},{"q":"每个孩子的____都不一样，有的爱说话，有的很害羞。","opts":["结果","作用","内容","性格"],"a":3,"exp":"“爱说话、很害羞” là mô tả tính cách của mỗi đứa trẻ, nên chọn 性格 (tính cách). 结果 (kết quả), 作用 (tác dụng), 内容 (nội dung) không dùng để tả người."},{"q":"你想送儿子生日礼物，我____你买一本故事书，他一定会喜欢。","opts":["判断","整理","建议","解决"],"a":2,"exp":"“建议你买……” (đề nghị bạn mua ...) là cách nói quen khi đưa ý kiến. 判断 (phán đoán), 整理 (sắp xếp), 解决 (giải quyết) không hợp nghĩa câu này."},{"q":"这个游戏太难了，孩子玩了一会儿就没有____了。","opts":["愉快","兴趣","合适","普遍"],"a":1,"exp":"“对……没有兴趣” (không có hứng thú với …) là cách kết hợp cố định, diễn tả đứa trẻ chơi một lát đã chán; 愉快 (vui vẻ), 合适 (phù hợp), 普遍 (phổ biến) không đi với “没有” trong câu này."},{"q":"妈妈每天都很忙，但是她从不忘记____孩子的学习和身体。","opts":["关心","骗","引起","得到"],"a":0,"exp":"Đáp án 关心 (quan tâm): “关心孩子的学习和身体” là cách nói hợp lý. 骗 (lừa), 引起 (gây ra), 得到 (nhận được) không kết hợp được với tân ngữ này."}],"order":[{"chunks":["他","通过","努力","得到了","老师的表扬。"],"vi":"Anh ấy nhờ nỗ lực mà nhận được lời khen của thầy cô."},{"chunks":["父母","应该","经常","关心","孩子的心情。"],"vi":"Bố mẹ nên thường xuyên quan tâm đến tâm trạng của con."},{"chunks":["这个年龄段的","孩子","普遍","比较好动。"],"vi":"Trẻ ở độ tuổi này nhìn chung khá hiếu động."},{"chunks":["我们","要","选择","合适的","教育方法。"],"vi":"Chúng ta phải chọn phương pháp giáo dục phù hợp."}],"read":{"text":"我儿子今年七岁，性格有些害羞，在学校里不爱说话。老师建议我多陪他聊聊天，不要总是批评他。开始我觉得没有用，后来发现，只要我认真听他说话，他就愿意告诉我学校里发生的事情。上个星期，他还高兴地对我说，他想参加学校的唱歌比赛。我听了非常愉快，马上鼓励他好好儿准备。现在我明白了，关心孩子比批评孩子更重要。","vi":"Con trai tôi năm nay bảy tuổi, tính cách hơi ngại ngùng, ở trường không thích nói chuyện. Cô giáo đề nghị tôi nên ngồi trò chuyện với con nhiều hơn, đừng lúc nào cũng phê bình con. Lúc đầu tôi thấy chẳng có ích gì, về sau mới nhận ra rằng chỉ cần tôi chăm chú nghe con nói thì con sẽ sẵn lòng kể cho tôi những chuyện xảy ra ở trường. Tuần trước, con còn vui vẻ nói với tôi là muốn tham gia cuộc thi hát của trường. Nghe xong tôi rất vui, lập tức khích lệ con chuẩn bị cho thật tốt. Giờ tôi đã hiểu: quan tâm đến con quan trọng hơn là phê bình con.","qs":[{"q":"老师建议“我”怎么做？","opts":["多批评孩子","多陪孩子聊天","让孩子换学校","不要管孩子"],"a":1,"exp":"Bài viết: cô giáo khuyên “多陪他聊聊天，不要总是批评他” (hãy trò chuyện với con nhiều hơn, đừng luôn phê bình), nên đáp án đúng là 多陪孩子聊天; ba đáp án kia trái với lời khuyên này."},{"q":"儿子为什么愿意说学校里的事情？","opts":["因为“我”给他买了礼物","因为老师批评了他","因为他唱歌唱得好","因为“我”认真听他说话"],"a":3,"exp":"Bài nói “只要我认真听他说话，他就愿意告诉我……”, nên nguyên nhân là “tôi” chăm chú lắng nghe. Quà, bị thầy phê bình, hát hay đều không phải lý do."},{"q":"这段话最后想说明什么？","opts":["孩子应该多参加比赛","老师比父母更重要","害羞的孩子不用管","关心孩子比批评孩子更有用"],"a":3,"exp":"Câu cuối nói “quan tâm con quan trọng hơn phê bình con”, tức ý chính là 关心孩子比批评孩子更有用; các đáp án khác (thi đấu, giáo viên quan trọng hơn cha mẹ, mặc kệ trẻ nhút nhát) không phải ý của bài."}]},"write":[{"word":"通过","hint":"Nói rằng nhờ đọc sách mà em học được nhiều kiến thức.","model":"通过看书，我学到了很多知识。","py":"Tōngguò kàn shū, wǒ xué dào le hěn duō zhīshi.","vi":"Nhờ đọc sách, tôi học được rất nhiều kiến thức."},{"word":"缺少","hint":"Nói đứa trẻ này thiếu tự tin, cần mọi người khích lệ.","model":"这个孩子缺少自信，需要大家的鼓励。","py":"Zhège háizi quēshǎo zìxìn, xūyào dàjiā de gǔlì.","vi":"Đứa trẻ này thiếu tự tin, cần sự khích lệ của mọi người."},{"word":"为了","hint":"Nói để con phát triển khỏe mạnh, bố mẹ ngày nào cũng cùng con vận động.","model":"为了让孩子健康发展，父母每天陪他运动。","py":"Wèile ràng háizi jiànkāng fāzhǎn, fùmǔ měitiān péi tā yùndòng.","vi":"Để con phát triển khỏe mạnh, bố mẹ ngày nào cũng cùng con vận động."}]},"16":{"fill":[{"q":"我们要珍惜时间，不能把时间____在玩游戏上。","opts":["复习","浪费","准备","打算"],"a":1,"exp":"Đáp án 浪费 (lãng phí): “把时间浪费在……上” là cấu trúc quen thuộc, nghĩa là dùng thời gian một cách vô ích. 复习 (ôn tập), 准备 (chuẩn bị), 打算 (dự định) không hợp ý khuyên này."},{"q":"明天有汉语考试，今晚我要认真____一下学过的生词。","opts":["拒绝","浪费","复习","放弃"],"a":2,"exp":"Mai có thi tiếng Hán, tối nay xem lại từ mới đã học nên dùng 复习 (ôn tập). 拒绝 (từ chối), 浪费 (lãng phí), 放弃 (từ bỏ) không hợp nghĩa."},{"q":"虽然他成绩很好，但是从不____，对同学也很客气。","opts":["骄傲","失望","冷静","诚实"],"a":0,"exp":"“成绩好但是从不……”, vế sau nói khách khí với bạn học, nên là 骄傲 (kiêu ngạo): không bao giờ kiêu ngạo. 失望 (thất vọng), 冷静 (bình tĩnh), 诚实 (thành thật) không đối lập với “thành tích tốt”."},{"q":"做作业不能太____，写完以后要再检查一遍。","opts":["尊重","成功","同情","马虎"],"a":3,"exp":"Vế sau là “viết xong phải kiểm tra lại một lần”, nghĩa là làm bài không được 马虎 (cẩu thả, qua loa); 尊重 (tôn trọng), 成功 (thành công), 同情 (đồng cảm) không hợp nghĩa."},{"q":"朋友请我周末去爬山，可是我要加班，只好____了他。","opts":["原谅","重视","拒绝","担心"],"a":2,"exp":"Đáp án 拒绝 (từ chối): vì phải tăng ca không đi được nên đành từ chối lời mời. 原谅 (tha thứ), 重视 (coi trọng), 担心 (lo lắng) không hợp ngữ cảnh."},{"q":"我们应该____每一个人，不管他做什么工作。","opts":["推到","尊重","放弃","同情"],"a":1,"exp":"“不管他做什么工作” thì ai cũng cần được 尊重 (tôn trọng). 推到 (đẩy ngã), 放弃 (từ bỏ), 同情 (thương hại) không hợp với ý “đối xử với mọi người”."}],"order":[{"chunks":["只要","认真复习","就能","考出好成绩。"],"vi":"Chỉ cần ôn tập nghiêm túc là có thể thi ra kết quả tốt."},{"chunks":["我们","一定要","重视","平时的积累。"],"vi":"Chúng ta nhất định phải coi trọng sự tích lũy hằng ngày."},{"chunks":["首先","要做好","课前","预习。"],"vi":"Trước hết phải làm tốt việc chuẩn bị bài trước giờ học."},{"chunks":["小李","把","作业","推到","明天了。"],"vi":"Tiểu Lý đã đẩy bài tập sang ngày mai."}],"read":{"text":"小张是我的同学，他的成绩很好，每次考试都是第一。可是最近一次比赛，他输给了一个不太有名的同学。小张刚开始很难过，但是他很快就冷静下来了。他对我说：“我以前有点儿骄傲，觉得自己什么都懂。其实别人也有很多值得学习的地方。”现在，他不但更努力地复习，还经常向周围的同学问问题。","vi":"Tiểu Trương là bạn học của tôi, thành tích rất tốt, kỳ thi nào cũng đứng nhất. Nhưng trong cuộc thi gần đây, cậu ấy lại thua một bạn không mấy nổi tiếng. Lúc đầu Tiểu Trương rất buồn, nhưng nhanh chóng bình tĩnh lại. Cậu nói với tôi: 'Trước đây mình hơi kiêu ngạo, tưởng cái gì mình cũng biết. Thật ra người khác cũng có nhiều điều đáng học hỏi.' Bây giờ cậu không những ôn tập chăm chỉ hơn mà còn thường xuyên hỏi các bạn xung quanh.","qs":[{"q":"小张最近为什么难过？","opts":["成绩一直不好","比赛输了","老师批评了他","同学不理他"],"a":1,"exp":"Bài viết nói Tiểu Trương thua bạn khác trong cuộc thi gần đây nên buồn, đáp án đúng là 比赛输了 (thua cuộc thi). Thành tích kém, bị thầy phê bình, bạn không để ý đều không được nhắc."},{"q":"小张觉得自己以前有什么问题？","opts":["有点儿骄傲","太马虎","不爱复习","不爱问问题"],"a":0,"exp":"Tiểu Trương tự nói “trước đây tôi hơi 骄傲 (kiêu ngạo), tưởng mình cái gì cũng biết”; bài không nói anh cẩu thả, lười ôn tập hay ngại hỏi bài, nên các đáp án kia sai."},{"q":"现在小张有什么变化？","opts":["不想参加比赛了","不再和同学说话","觉得自己很差","更努力，也愿意向别人学习"],"a":3,"exp":"Đáp án 更努力，也愿意向别人学习: bài nói cậu ấy ôn tập chăm chỉ hơn và thường hỏi bạn xung quanh. Cậu ấy đã bình tĩnh lại, nên không bỏ thi hay tự thấy mình kém."}]},"write":[{"word":"打算","hint":"Nói sau khi tốt nghiệp em dự định đi làm hai năm rồi ra nước ngoài học.","model":"毕业以后，我打算先工作两年，再去国外读书。","py":"Bìyè yǐhòu, wǒ dǎsuàn xiān gōngzuò liǎng nián, zài qù guówài dúshū.","vi":"Sau khi tốt nghiệp, tôi dự định đi làm hai năm trước rồi mới ra nước ngoài học."},{"word":"诚实","hint":"Nói đứa trẻ này rất thành thật, làm sai là báo ngay với bố mẹ.","model":"他是个很诚实的孩子，做错了事情会马上告诉父母。","py":"Tā shì ge hěn chéngshí de háizi, zuò cuò le shìqing huì mǎshàng gàosu fùmǔ.","vi":"Cậu bé rất thành thật, làm sai chuyện gì là báo ngay với bố mẹ."},{"word":"担心","hint":"An ủi bạn đừng lo, chỉ cần chuẩn bị nghiêm túc thì kỳ thi chắc chắn không sao.","model":"别担心，只要你认真准备，考试一定没问题。","py":"Bié dānxīn, zhǐyào nǐ rènzhēn zhǔnbèi, kǎoshì yídìng méi wèntí.","vi":"Đừng lo, chỉ cần bạn chuẩn bị nghiêm túc thì kỳ thi chắc chắn không có vấn đề."}]},"17":{"fill":[{"q":"两家饭店为了吸引客人，在价格上的____越来越厉害。","opts":["获得","竞争","发现","排列"],"a":1,"exp":"“价格上的____”需要名词，“竞争”（cạnh tranh）表示两家店争客人，符合语境。"},{"q":"____天气不好，今天的足球比赛只好改到下个星期。","opts":["虽然","另外","由于","然而"],"a":2,"exp":"“由于……只好……”表示原因和结果：vì thời tiết xấu nên đành dời trận đấu."},{"q":"冬天外面很冷，可是屋子里很____，我只穿一件薄衣服就够了。","opts":["暖和","安静","奇怪","高大"],"a":0,"exp":"只穿薄衣服就够，说明屋里很“暖和”（ấm áp）。"},{"q":"医生说他的病已经好了，可是他____觉得不舒服。","opts":["大约","另外","一共","仍然"],"a":3,"exp":"“可是……仍然……”表示情况没有改变：bệnh khỏi rồi nhưng vẫn thấy khó chịu."},{"q":"我以为这家店很贵，____价格比别的店还便宜。","opts":["其实","就算","另外","一直"],"a":0,"exp":"“其实”表示真实情况和想的不一样：thật ra giá còn rẻ hơn các tiệm khác."},{"q":"这个城市的____很好，夏天不太热，冬天也不太冷。","opts":["条件","阳光","气候","植物"],"a":2,"exp":"说夏天不太热、冬天不太冷，指的是一个地方长期的天气情况，即“气候”（khí hậu）。"}],"order":[{"chunks":["森林里","高大的植物","往往","能获得更多阳光。"],"vi":"Trong rừng, những cây cao lớn thường nhận được nhiều ánh nắng hơn."},{"chunks":["海底的世界","看上去","非常","安静。"],"vi":"Thế giới dưới đáy biển trông rất yên tĩnh."},{"chunks":["就算","是在","很深的海底","也能看到亮光。"],"vi":"Dù là ở đáy biển rất sâu cũng vẫn có thể nhìn thấy ánh sáng."},{"chunks":["他","对海洋里的","动物","特别感兴趣。"],"vi":"Anh ấy đặc biệt hứng thú với các loài động vật trong đại dương."}],"read":{"text":"上个月我和朋友去海边，第一次学习游到水下看鱼。刚下水时我有点儿紧张，可是水下比我想的安静得多。教练带我们游到深一点儿的地方，各种颜色的小鱼在身边游来游去，像在跳舞。教练说，人们对海洋了解得还很少，所以不能随便拿走那里的东西。回到岸上，我决定每年都来一次。","vi":"Tháng trước tôi cùng bạn ra biển, lần đầu học bơi xuống dưới nước để ngắm cá. Lúc mới xuống nước tôi hơi căng thẳng, nhưng dưới nước yên tĩnh hơn tôi nghĩ nhiều. Huấn luyện viên dẫn chúng tôi bơi tới chỗ sâu hơn một chút, những chú cá nhỏ đủ màu sắc bơi qua bơi lại quanh người, giống như đang nhảy múa. Huấn luyện viên nói con người hiểu về đại dương còn rất ít, vì vậy không được tùy tiện mang đồ ở đó đi. Lên bờ, tôi quyết định mỗi năm đều tới một lần.","qs":[{"q":"水下和“我”想的有什么不同？","opts":["比想的安静","比想的冷","比想的热闹","比想的浅"],"a":0,"exp":"Bài viết nói “水下比我想的安静得多” (dưới nước yên tĩnh hơn tôi nghĩ nhiều), nên chọn 比想的安静; các đáp án lạnh, náo nhiệt, nông đều không được nhắc tới."},{"q":"教练为什么说不能随便拿走海里的东西？","opts":["因为那些东西都很贵","因为带回家很麻烦","因为人们对海洋还了解得很少","因为小鱼会不高兴"],"a":2,"exp":"Huấn luyện viên nói con người còn hiểu biết rất ít về biển (了解得还很少), “所以” không được tùy tiện mang đồ đi, nên lý do là đáp án C. Đắt tiền, phiền phức, cá nhỏ không vui đều không phải lý do được nêu."},{"q":"回到岸上以后，“我”有什么打算？","opts":["再也不下水了","买几条小鱼带回家","去当教练","每年都再来一次"],"a":3,"exp":"Câu cuối bài: lên bờ rồi “tôi quyết định mỗi năm đều đến một lần”, đúng với đáp án 每年都再来一次; không nhắc đến chuyện không xuống nước nữa, mua cá, hay làm huấn luyện viên."}]},"write":[{"word":"获得","hint":"Nói rằng anh ấy đã giành được giải nhất trong cuộc thi.","model":"他在比赛中获得了第一名。","py":"Tā zài bǐsài zhōng huòdé le dì-yī míng.","vi":"Anh ấy giành được hạng nhất trong cuộc thi."},{"word":"往往","hint":"Nói rằng cuối tuần bạn thường ngủ đến mười giờ mới dậy.","model":"周末我往往睡到十点才起床。","py":"Zhōumò wǒ wǎngwǎng shuì dào shí diǎn cái qǐchuáng.","vi":"Cuối tuần tôi thường ngủ đến mười giờ mới dậy."},{"word":"发现","hint":"Nói rằng bạn phát hiện ví tiền không còn trong túi.","model":"我发现钱包不在包里了。","py":"Wǒ fāxiàn qiánbāo bú zài bāo lǐ le.","vi":"Tôi phát hiện ví tiền không còn trong túi nữa."}]},"18":{"fill":[{"q":"我搬家以后，一直没有和以前的同学____，不知道他们现在怎么样。","opts":["使用","需要","联系","解决"],"a":2,"exp":"“和……联系”（liên lạc với…）是固定搭配，符合“不知道他们现在怎么样”。"},{"q":"这个城市的路太复杂了，我第一次来，很容易____。","opts":["迷路","付款","购物","降落"],"a":0,"exp":"路复杂又是第一次来，所以容易“迷路”（lạc đường）。"},{"q":"现在会用手机上网的老人很____，不再是少数了。","opts":["危险","奇特","普遍","安静"],"a":2,"exp":"“不再是少数”说明这种情况很多，用“普遍”（phổ biến）。"},{"q":"为了安全，你的手机____不要告诉别人。","opts":["地址","密码","价格","作用"],"a":1,"exp":"为了安全而不能告诉别人的是“密码”（mật khẩu）。"},{"q":"这件衣服质量很好，____也不贵，所以我买了两件。","opts":["世纪","邮局","地点","价格"],"a":3,"exp":"“也不贵”说的是“价格”（giá cả）。"},{"q":"我家离地铁站很近，坐车去哪儿都很____。","opts":["巨大","方便","奇特","危险"],"a":1,"exp":"离地铁站近，去哪儿都容易，所以是“方便”（thuận tiện）。"}],"order":[{"chunks":["科学技术的发展","使","我们的生活","越来越方便。"],"vi":"Sự phát triển của khoa học kỹ thuật khiến cuộc sống của chúng ta ngày càng tiện lợi."},{"chunks":["他","用手机地图","找到了","那个地点。"],"vi":"Anh ấy dùng bản đồ trên điện thoại tìm được địa điểm đó."},{"chunks":["只要","打开手机","就能","看到最新的新闻。"],"vi":"Chỉ cần mở điện thoại là có thể xem được tin tức mới nhất."},{"chunks":["孩子们","对新技术","总是","很有兴趣。"],"vi":"Bọn trẻ lúc nào cũng rất hứng thú với công nghệ mới."}],"read":{"text":"我爷爷今年七十岁了，以前他总说手机太复杂，不愿意学。去年孙女教他用手机跟国外的姑姑视频聊天，他在手机里看到了姑姑的脸，高兴极了。后来，他每天都用手机看新闻、听音乐。上个星期他出门迷了路，自己用手机地图找到了回家的路。回来以后，他笑着对我们说：“这个小东西真有用！”","vi":"Ông nội tôi năm nay bảy mươi tuổi, trước đây ông luôn nói điện thoại quá phức tạp nên không muốn học. Mùa hè năm ngoái, cháu gái dạy ông dùng điện thoại gọi video trò chuyện với cô ở nước ngoài, ông nhìn thấy gương mặt của cô trong điện thoại, vui vô cùng. Sau đó, mỗi ngày ông đều dùng điện thoại xem tin tức, nghe nhạc. Tuần trước ông ra ngoài bị lạc đường, tự dùng bản đồ trên điện thoại tìm được đường về nhà. Về đến nhà, ông cười nói với chúng tôi: “Vật nhỏ này đúng là có ích!”","qs":[{"q":"爷爷以前为什么不愿意用手机？","opts":["因为手机太贵","因为他没有朋友","因为他觉得手机不容易学","因为他的眼睛不好"],"a":2,"exp":"Đáp án 因为他觉得手机不容易学: bài viết nói ông cho rằng điện thoại “太复杂” (quá phức tạp) nên không muốn học. Không hề nhắc tới giá đắt, không có bạn hay mắt kém."},{"q":"孙女教爷爷做什么？","opts":["用手机和国外的姑姑视频聊天","用手机付款买东西","用手机玩儿游戏","用手机发电子邮件"],"a":0,"exp":"Bài nói cháu gái dạy ông dùng điện thoại 视频聊天 (gọi video) với cô ở nước ngoài; thanh toán, chơi game, gửi email không phải điều cháu gái dạy."},{"q":"爷爷最后说“这个小东西真有用”，是因为什么？","opts":["手机帮他买到了便宜的东西","手机地图帮他找到了回家的路","手机让他认识了新朋友","手机里的音乐很好听"],"a":1,"exp":"Tuần trước ông bị lạc, nhờ bản đồ trên điện thoại mà tự về được nhà, sau đó mới nói “cái thứ nhỏ này thật có ích”, nên chọn đáp án B. Mua đồ rẻ, quen bạn mới, nghe nhạc không phải nguyên nhân."}]},"write":[{"word":"解决","hint":"Nói rằng máy tính của bạn hỏng, bạn bè đã giúp bạn giải quyết vấn đề này.","model":"我的电脑坏了，朋友帮我解决了这个问题。","py":"Wǒ de diànnǎo huài le, péngyou bāng wǒ jiějué le zhège wèntí.","vi":"Máy tính của tôi bị hỏng, bạn đã giúp tôi giải quyết vấn đề này."},{"word":"需要","hint":"Nói rằng đi du lịch nước ngoài cần làm hộ chiếu.","model":"去国外旅游需要办护照。","py":"Qù guówài lǚyóu xūyào bàn hùzhào.","vi":"Đi du lịch nước ngoài cần làm hộ chiếu."},{"word":"节约","hint":"Nói rằng chúng ta nên tiết kiệm nước và bảo vệ môi trường.","model":"我们应该节约用水，保护环境。","py":"Wǒmen yīnggāi jiéyuē yòng shuǐ, bǎohù huánjìng.","vi":"Chúng ta nên tiết kiệm nước, bảo vệ môi trường."}]},"19":{"fill":[{"q":"我租的房子下个月就要____了，得赶紧找新房子。","opts":["到期","占线","禁止","满意"],"a":0,"exp":"到期 (hết hạn) dùng cho hợp đồng thuê nhà đến kỳ hạn, nên phải tìm nhà mới; 占线 (máy bận) chỉ dùng cho điện thoại, 禁止 (cấm) và 满意 (hài lòng) không đi với “房子要……了”."},{"q":"我给房东打了三次电话，可是一直____，没打通。","opts":["满意","占线","选择","着急"],"a":1,"exp":"Đáp án 占线 (máy bận): gọi không được vì đối phương đang nói chuyện, gọi là “占线”. 满意 (hài lòng), 选择 (lựa chọn), 着急 (sốt ruột) không giải thích được việc không kết nối."},{"q":"比赛开始前，____们在场边认真地热身。","opts":["房东","广告","观众","运动员"],"a":3,"exp":"Người khởi động ở sân trước trận đấu là 运动员 (vận động viên). 观众 (khán giả) là người xem; 房东 (chủ nhà), 广告 (quảng cáo) không hợp ngữ cảnh."},{"q":"这家饭店的菜又好吃又便宜，我们都很____。","opts":["禁止","数字","满意","到期"],"a":2,"exp":"“很+满意” (rất hài lòng) diễn tả cảm giác về món ăn ngon, rẻ. 禁止 (cấm), 数字 (con số), 到期 (đến hạn) không dùng được sau “很” với nghĩa này."},{"q":"图书馆里____大声讲话，请大家遵守规定。","opts":["条件","禁止","环境","数字"],"a":1,"exp":"“禁止 + động từ” nghĩa là cấm làm việc gì, hợp với nội quy thư viện “cấm nói to”; 条件 (điều kiện), 环境 (môi trường), 数字 (con số) không thể đứng trước động từ như vậy."},{"q":"这项运动对场地的要求不高，只要有一块空地就行，____很简单。","opts":["房东","广告","条件","数字"],"a":2,"exp":"Đáp án 条件 (điều kiện): chỉ những yêu cầu cần có để làm việc, câu nói điều kiện rất đơn giản (chỉ cần một bãi đất trống). 房东 (chủ nhà), 广告 (quảng cáo), 数字 (con số) không hợp."}],"order":[{"chunks":["这套房子","离地铁站很近，","交通非常方便。"],"vi":"Căn nhà này gần ga tàu điện ngầm, giao thông rất thuận tiện."},{"chunks":["小王","把广告上的","电话号码","记错了。"],"vi":"Tiểu Vương đã ghi sai số điện thoại trên quảng cáo."},{"chunks":["比赛时","观众们","要保持","安静。"],"vi":"Khi thi đấu, khán giả phải giữ yên lặng."},{"chunks":["我想","租一套","周围很安静的","房子。"],"vi":"Tôi muốn thuê một căn nhà xung quanh rất yên tĩnh."}],"read":{"text":"小李下个月要搬家，所以最近一直在找房子。他看了很多广告，也给几位房东打过电话。第一套环境不错，可是房租太贵。第二套虽然便宜，但是离公司很远，交通不方便。第三套房间不大，不过很安静，房东人也很好。小李想了想，决定周末再去看一次。","vi":"Tháng sau Tiểu Lý sẽ chuyển nhà, nên dạo này anh ấy luôn tìm nhà. Anh xem rất nhiều quảng cáo, cũng gọi điện cho mấy chủ nhà. Căn thứ nhất môi trường tốt nhưng tiền thuê quá đắt. Căn thứ hai tuy rẻ nhưng cách công ty rất xa, giao thông không thuận tiện. Căn thứ ba phòng không lớn nhưng rất yên tĩnh, chủ nhà cũng tốt. Tiểu Lý suy nghĩ rồi quyết định cuối tuần đi xem thêm một lần.","qs":[{"q":"小李为什么要找房子？","opts":["找到了新工作","房东要涨价","朋友要来住","下个月要搬家"],"a":3,"exp":"Câu đầu bài nói “小李下个月要搬家” (tháng sau anh Lý chuyển nhà) nên mới đi tìm nhà; bài không nói có việc mới, chủ nhà tăng giá hay bạn đến ở."},{"q":"小李为什么对第二套房子不满意？","opts":["房租太贵","房间太小","离公司远，交通也不方便","周围太吵"],"a":2,"exp":"Căn thứ hai tuy rẻ nhưng xa công ty và giao thông bất tiện, nên đáp án C đúng. “Tiền thuê quá đắt” là vấn đề của căn thứ nhất, không phải căn thứ hai."},{"q":"周末小李打算做什么？","opts":["再去看一次第三套房子","去给房东交钱","再看第四套房子","去公司上班"],"a":0,"exp":"Anh quyết định cuối tuần đi xem lại một lần nữa, và chỉ căn thứ ba là yên tĩnh, chủ nhà tốt, không có nhược điểm, nên là đi xem lại căn thứ ba; căn một thì tiền thuê đắt, căn hai thì xa công ty."}]},"write":[{"word":"周围","hint":"Nói quanh nhà bạn có những gì (công viên, siêu thị...).","model":"我家周围有公园和超市，生活很方便。","py":"Wǒ jiā zhōuwéi yǒu gōngyuán hé chāoshì, shēnghuó hěn fāngbiàn.","vi":"Xung quanh nhà tôi có công viên và siêu thị, sinh hoạt rất tiện."},{"word":"着急","hint":"Nói trận đấu sắp bắt đầu mà anh ấy chưa đến, mọi người đều sốt ruột.","model":"比赛马上就要开始了，他还没到，大家都很着急。","py":"Bǐsài mǎshàng jiù yào kāishǐ le, tā hái méi dào, dàjiā dōu hěn zháojí.","vi":"Trận đấu sắp bắt đầu rồi mà anh ấy vẫn chưa đến, mọi người đều rất sốt ruột."},{"word":"满意","hint":"Nói bạn hài lòng với căn nhà đang thuê vì chủ nhà tốt.","model":"我对现在租的房子很满意，因为房东人很好。","py":"Wǒ duì xiànzài zū de fángzi hěn mǎnyì, yīnwèi fángdōng rén hěn hǎo.","vi":"Tôi rất hài lòng với căn nhà đang thuê, vì chủ nhà rất tốt."}]},"20":{"fill":[{"q":"北京和海南的____很不一样，冬天北京很冷，海南却像夏天。","opts":["距离","行李","气候","导游"],"a":2,"exp":"Đáp án 气候 (khí hậu): nói mùa đông Bắc Kinh lạnh còn Hải Nam như mùa hè là nói tình hình thời tiết chung của vùng, tức khí hậu. 距离 (khoảng cách), 行李 (hành lý), 导游 (hướng dẫn viên) sai nghĩa."},{"q":"我们明天早上七点____，请大家别迟到。","opts":["出发","推迟","新鲜","印象"],"a":0,"exp":"“七点出发” nghĩa là 7 giờ khởi hành (出发 = xuất phát). 推迟 (hoãn lại) cần nói rõ hoãn bao lâu nên không dùng như vậy; 新鲜 (tươi) và 印象 (ấn tượng) không hợp nghĩa."},{"q":"因为下大雪，航班____了两个小时。","opts":["放松","推迟","出发","印象"],"a":1,"exp":"推迟 (hoãn lại): “推迟了两个小时” nghĩa là chuyến bay bị lùi hai tiếng vì tuyết lớn. 放松 (thư giãn), 出发 (xuất phát), 印象 (ấn tượng) không hợp với “航班” và “了两个小时”."},{"q":"这家店的鱼很____，是早上刚从海里捞上来的。","opts":["新鲜","暖和","风景","机会"],"a":0,"exp":"Cá vừa vớt từ biển lên sáng nay là 新鲜 (tươi); 暖和 (ấm áp) dùng cho thời tiết hay quần áo, 风景 (phong cảnh) và 机会 (cơ hội) không mô tả được cá."},{"q":"我们的____很有经验，一路上给大家讲了不少有意思的故事。","opts":["季节","行李","导游","目的地"],"a":2,"exp":"Đáp án 导游 (hướng dẫn viên du lịch): người kể chuyện và dẫn mọi người đi suốt chuyến là hướng dẫn viên. 季节 (mùa), 行李 (hành lý), 目的地 (điểm đến) không thể “có kinh nghiệm” hay kể chuyện."},{"q":"现在才七点，离起飞还有三个小时，肯定____。","opts":["来不及","担心","放松","来得及"],"a":3,"exp":"Mới 7 giờ, còn ba tiếng nữa máy bay mới cất cánh, thời gian còn nhiều nên chắc chắn 来得及 (kịp). 来不及 (không kịp) nghĩa ngược lại; 担心 (lo lắng), 放松 (thư giãn) không hợp với “肯定”."}],"order":[{"chunks":["请把","登机牌","给我","看一下。"],"vi":"Xin hãy đưa thẻ lên máy bay cho tôi xem một chút."},{"chunks":["北方和南方","的气候","有很大","区别。"],"vi":"Khí hậu miền Bắc và miền Nam có sự khác biệt rất lớn."},{"chunks":["导游","给游客们","介绍了","这座城市的特点。"],"vi":"Hướng dẫn viên giới thiệu với du khách đặc điểm của thành phố này."},{"chunks":["即使下雨，","我们也","要按时","出发。"],"vi":"Dù trời mưa, chúng tôi cũng phải xuất phát đúng giờ."}],"read":{"text":"去年秋天，我一个人去了南方的一个小城。出发以前我没有做计划，只买了一张火车票。那里的风景很美，空气也很新鲜。白天我在老街上慢慢地走，晚上就在小饭馆儿里吃当地的小吃。虽然没有人陪我，但我一点儿也不觉得孤单。回来以后，我觉得压力少了很多。","vi":"Mùa thu năm ngoái, tôi một mình đến một thành phố nhỏ ở miền Nam. Trước khi đi tôi không lập kế hoạch, chỉ mua một vé tàu hỏa. Phong cảnh ở đó rất đẹp, không khí cũng rất trong lành. Ban ngày tôi thong thả đi dạo trên phố cổ, buổi tối thì ăn đồ ăn vặt địa phương ở quán nhỏ. Tuy không có ai đi cùng nhưng tôi chẳng thấy cô đơn chút nào. Sau khi về, tôi thấy áp lực giảm đi nhiều.","qs":[{"q":"这次旅行前，“我”的计划是怎样的？","opts":["计划得很详细","几乎没有计划，只买了车票","和朋友商量了很久","请了一位导游"],"a":1,"exp":"Bài viết nói trước khi đi hầu như không lập kế hoạch, chỉ mua một vé tàu hỏa, khớp đáp án B. Lập kế hoạch chi tiết, bàn bạc lâu với bạn, thuê hướng dẫn viên đều sai."},{"q":"旅行回来以后，“我”有什么变化？","opts":["更喜欢北方了","朋友变多了","工作更忙了","觉得压力小了"],"a":3,"exp":"Câu cuối nói sau chuyến đi “tôi thấy áp lực giảm đi nhiều”, đúng với đáp án 觉得压力小了; bài không nói thích phương Bắc hơn, thêm bạn hay công việc bận hơn."},{"q":"从这段话可以知道，“我”对这次旅行的感觉是：","opts":["很失望","有点儿后悔","很满意","觉得太累"],"a":2,"exp":"Đáp án 很满意: người viết khen cảnh đẹp, không khí trong lành, không thấy cô đơn và về nhà bớt áp lực, cho thấy rất hài lòng. Không có chi tiết nào về thất vọng, hối hận hay mệt."}]},"write":[{"word":"机会","hint":"Nói sang năm hy vọng có cơ hội đến Vân Nam ngắm phong cảnh.","model":"明年我希望有机会去云南看看那里的风景。","py":"Míngnián wǒ xīwàng yǒu jīhuì qù Yúnnán kànkan nàlǐ de fēngjǐng.","vi":"Sang năm tôi hy vọng có cơ hội đến Vân Nam xem phong cảnh ở đó."},{"word":"担心","hint":"Nói bạn hơi lo hành lý bị mất nên luôn để bên mình.","model":"我有点儿担心行李会丢，所以一直把它放在身边。","py":"Wǒ yǒudiǎnr dānxīn xíngli huì diū, suǒyǐ yìzhí bǎ tā fàng zài shēnbiān.","vi":"Tôi hơi lo hành lý sẽ bị mất nên luôn để nó bên cạnh mình."},{"word":"特点","hint":"Nói đặc điểm món ăn quê bạn (vừa chua vừa ngọt) mà nhiều du khách thích.","model":"我家乡菜的特点是又酸又甜，很多游客都喜欢。","py":"Wǒ jiāxiāng cài de tèdiǎn shì yòu suān yòu tián, hěn duō yóukè dōu xǐhuan.","vi":"Đặc điểm món ăn quê tôi là vừa chua vừa ngọt, rất nhiều du khách thích."}]}};
